  const waadaBadge = waadaLabel ? `<span class="wada-badge ${customer.promiseDate < waadaToday ? 'wada-badge-broken waada-pulse' : 'wada-badge-upcoming'}">${escapeHtml(waadaLabel)}</span>` : '';
  const waadaSectionHtml = `<section class="profile-waada-section" aria-label="${t('prof_waada_aria')}"><h4>${t('prof_waada_heading')} ${helpButtonMarkup('waada')}</h4><p class="profile-waada-current">${customer.promiseDate ? `${escapeHtml(t('prof_waada_promise', null, { date: customer.promiseDate }))}${customer.promiseAmount ? ` · PKR ${Number(customer.promiseAmount).toLocaleString()}` : ''}${customer.promiseNote ? ` · “${escapeHtml(customer.promiseNote)}”` : ''} ${waadaBadge}` : t('prof_waada_none')}</p>${waadaScoreBadgeHtml(state, customer, waadaToday)}<div class="waada-chip-row" role="group" aria-label="${t('prof_waada_chips_aria')}"><button type="button" class="secondary-button waada-chip-btn" data-profile-waada-chip="plus2">${t('prof_waada_chip_2')}</button><button type="button" class="secondary-button waada-chip-btn" data-profile-waada-chip="plus5">${t('prof_waada_chip_5')}</button><button type="button" class="secondary-button waada-chip-btn" data-profile-waada-chip="tenth">${t('prof_waada_chip_10th')}</button></div><div class="waada-chip-custom"><label for="profileWaadaCustomDate">${t('prof_waada_custom')}</label><input id="profileWaadaCustomDate" type="date" aria-label="${t('prof_waada_custom_aria')}"><button type="button" class="primary-button" id="profileWaadaSetCustomBtn">${t('prof_waada_set')}</button><button type="button" class="secondary-button text-button danger" id="profileWaadaClearBtn">${t('prof_waada_clear')}</button></div></section>`;
  // SISP-15: profile complaint history — this customer's register entries only.
