  const paymentSlipSendDisabled = Boolean(paymentSlipPref && paymentSlipPref.doNotMessage) || !paymentSlipCurrent;
  const paymentSlipSends = () => findPaymentSlipSends(loadPaymentSlipSentLog(), customer.id);
