function signedOneSeriesSvg(rows,{key,label,title,isMoney=false}={}) {
  const values=rows.map(row=>row[key]).filter(value=>Number.isFinite(value));if(!values.length)return '';
  const width=720,height=220,left=76,right=12,top=14,bottom=38,plotWidth=width-left-right,plotHeight=height-top-bottom,low=Math.min(0,...values),high=Math.max(0,...values),span=Math.max(1,high-low),groupWidth=plotWidth/Math.max(rows.length,1),barWidth=Math.min(30,groupWidth*.42),zeroY=top+(high/span)*plotHeight;
  const ticks=[high,0,low].filter((value,index,array)=>array.indexOf(value)===index),grid=ticks.map(value=>{const y=top+((high-value)/span)*plotHeight;return `<line x1="${left}" y1="${y}" x2="${width-right}" y2="${y}" class="chart-grid-line"/><text x="${left-7}" y="${y+4}" text-anchor="end" class="chart-axis-label">${phase3Cell(chartAxis(value,isMoney))}</text>`;}).join('');
  const bars=rows.map((row,index)=>{const value=row[key],center=left+groupWidth*(index+.5),valueY=top+((high-value)/span)*plotHeight,y=Math.min(zeroY,valueY),h=Math.max(1,Math.abs(zeroY-valueY));return `${Number.isFinite(value)?`<rect x="${center-barWidth/2}" y="${y}" width="${barWidth}" height="${h}" rx="3" class="${value<0?'chart-bar-negative':'chart-bar-first'}"><title>${phase3Cell(label)} · ${phase3Cell(row.month)}: ${phase3Cell(isMoney?formatAmount(value):value)}</title></rect>`:''}<text x="${center}" y="${height-12}" text-anchor="middle" class="chart-month-label">${phase3Cell(shortMonth(row.month))}</text>`;}).join('');
  const description=rows.map(row=>`${row.month}: ${Number.isFinite(row[key])?row[key]:'not recorded'}`).join('; ');
  return `<svg class="phase3-chart-svg" viewBox="0 0 ${width} ${height}" role="img" aria-label="${phase3Cell(title)}"><title>${phase3Cell(title)}</title><desc>${phase3Cell(description)}</desc>${grid}${bars}</svg>`;
}
function categoryBarsSvg(rows,{title,isMoney=true}={}) {
  const values=rows.filter(row=>Number.isFinite(row.value));if(!values.length)return '';
  const width=720,left=176,right=94,top=18,rowHeight=34,bottom=16,height=Math.max(130,top+values.length*rowHeight+bottom),plotWidth=width-left-right,maximum=Math.max(...values.map(row=>row.value),1),barHeight=15;
  const grid=[0,.5,1].map(ratio=>{const x=left+plotWidth*ratio;return `<line x1="${x}" y1="${top-5}" x2="${x}" y2="${height-bottom+1}" class="chart-grid-line"/><text x="${x}" y="${height-2}" text-anchor="middle" class="chart-axis-label">${phase3Cell(chartAxis(maximum*ratio,isMoney))}</text>`;}).join('');
  const bars=values.map((row,index)=>{const y=top+index*rowHeight,label=String(row.label??''),short=label.length>26?`${label.slice(0,24)}…`:label,barWidth=Math.max(row.value>0?2:0,row.value/maximum*plotWidth),display=isMoney?formatAmount(row.value):String(row.value);return `<text x="${left-9}" y="${y+barHeight-2}" text-anchor="end" class="chart-axis-label">${phase3Cell(short)}</text><rect x="${left}" y="${y}" width="${barWidth}" height="${barHeight}" rx="4" class="chart-bar-first"><title>${phase3Cell(label)}: ${phase3Cell(display)}</title></rect><text x="${width-right+7}" y="${y+barHeight-2}" class="chart-axis-label">${phase3Cell(display)}</text>`;}).join('');
  const description=values.map(row=>`${row.label}: ${row.value}`).join('; ');
  return `<svg class="phase3-chart-svg category-chart-svg" viewBox="0 0 ${width} ${height}" role="img" aria-label="${phase3Cell(title)}"><title>${phase3Cell(title)}</title><desc>${phase3Cell(description)}</desc>${grid}${bars}</svg>`;
}
function prepareAreaIntelFilters(data) {
  const month=$('#areaIntelMonth'),from=$('#areaIntelFrom'),to=$('#areaIntelTo');if(!month||!from||!to)return;
  const history=monthsForHistory(new Date()),oldMonth=month.value,hadDates=Boolean(from.value&&to.value);
  month.innerHTML=`<option value="">Custom date range</option>${history.map(value=>`<option value="${value}">${escapeHtml(monthName(value))}</option>`).join('')}`;
  month.value=history.includes(oldMonth)?oldMonth:hadDates?'':data.currentMonth;
  from.max=data.asOf;to.max=data.asOf;
  if(!hadDates){from.value=`${data.currentMonth}-01`;to.value=data.asOf;}
}
let areaSortKey = null;
let areaSortAsc = true;
let areaSearchQuery = '';

function areaIntelMetric(label, display, missing, title) {
  const titleAttr = title ? ` title="${phase3Cell(title)}"` : '';
  if (missing) return `<div class="area-intel-metric"><span>${label}</span><span class="area-intel-missing"${titleAttr}>${phase3Cell(display)}</span></div>`;
  return `<div class="area-intel-metric"><span>${label}</span><strong${titleAttr}>${phase3Cell(display)}</strong></div>`;
}
function areaIntelSectionMetrics(row) {
  const amountOrMissing = value => value === null ? null : formatAmount(value);
  return [
    areaIntelMetric('Customers · current roster', String(row.totalCustomers), false),
    areaIntelMetric('Active customers', row.activeCustomers === null ? 'Not recorded for this historical date' : String(row.activeCustomers), row.activeCustomers === null, row.activeCustomerSource),
    areaIntelMetric('Monthly billing', amountOrMissing(row.billedAmount), row.billedAmount === null),
    areaIntelMetric('Collected', amountOrMissing(row.collectedAmount), row.collectedAmount === null),
    areaIntelMetric('Outstanding', amountOrMissing(row.outstanding), row.outstanding === null),
    areaIntelMetric('Collection rate', row.collectionRate === null ? 'Not set' : `${row.collectionRate}%`, row.collectionRate === null),
    areaIntelMetric('Average customer value', amountOrMissing(row.averageCustomerValue), row.averageCustomerValue === null),
    areaIntelMetric('Expenses', amountOrMissing(row.expenses), row.expenses === null, row.expensesSource),
    areaIntelMetric('Estimated profit', amountOrMissing(row.estimatedProfit), row.estimatedProfit === null, row.estimatedProfitBasis),
    areaIntelMetric(t('zby_provisioned_label'), row.provisionedMbps === null || row.provisionedMbps === undefined ? '—' : `${row.provisionedMbps} Mbps`, row.provisionedMbps === null || row.provisionedMbps === undefined, row.unresolvedSpeedCount > 0 ? t('zby_unresolved_title', null, { count: row.unresolvedSpeedCount }) : ''),
    areaIntelMetric(t('zby_avg_speed_label'), row.avgSpeedMbps === null || row.avgSpeedMbps === undefined ? '—' : `${row.avgSpeedMbps} Mbps`, row.avgSpeedMbps === null || row.avgSpeedMbps === undefined),
    areaIntelMetric(t('zby_yield_label'), row.yieldPkrPerMbps === null || row.yieldPkrPerMbps === undefined ? '—' : formatAmount(row.yieldPkrPerMbps), row.yieldPkrPerMbps === null || row.yieldPkrPerMbps === undefined),
    ...(row.unresolvedSpeedCount > 0 ? [areaIntelMetric(t('zby_unresolved_label'), String(row.unresolvedSpeedCount), false)] : []),
  ].join('');
}
function areaIntelNoZoneNote(count) {
  return count ? `<p class="area-intel-no-zone">Without a zone: ${count} customer${count === 1 ? '' : 's'}</p>` : '';
}
function areaIntelCardSection(section) {
  const level = section.level === 'unassigned' ? 'Unassigned' : section.level;
  const name = phase3Cell(section.label.replace(/^(?:Area|Mohalla|Zone):\s*/, ''));
  return `<section class="area-intel-section"><h5><span class="area-intel-level">${phase3Cell(level)}</span> ${name}</h5><div class="area-intel-metrics">${areaIntelSectionMetrics(section.row)}</div>${areaIntelNoZoneNote(section.withoutZoneCustomers)}${section.children.map(areaIntelCardSection).join('')}</section>`;
}
function renderAreaIntelligenceCardsHtml(areaRows) {
  return groupAreaIntelligenceCards(areaRows).map(group => {
    const rootName = phase3Cell((group.root ? group.root.label : group.rootArea).replace(/^(?:Area|Mohalla|Zone):\s*/, ''));
    const rootLevel = group.root ? (group.root.level === 'unassigned' ? 'Unassigned' : group.root.level) : 'Area';
    const rootBody = group.root ? `<div class="area-intel-metrics">${areaIntelSectionMetrics(group.root.row)}</div>${areaIntelNoZoneNote(group.root.withoutZoneCustomers)}${group.root.children.map(areaIntelCardSection).join('')}` : '';
    return `<article class="area-intel-card"><header class="area-intel-card-header"><span class="area-intel-level">${phase3Cell(rootLevel)}</span><h4>${rootName}</h4></header>${rootBody}${areaIntelNoZoneNote(group.orphanWithoutZoneCustomers)}${group.children.map(areaIntelCardSection).join('')}</article>`;
  }).join('');
}
function renderAreaSummaryCardsHtml(cards) {
  return (cards ?? []).map(card => `<article class="area-intel-card"><header class="area-intel-card-header"><span class="area-intel-level">${phase3Cell(card.level)}</span><h4>${phase3Cell(card.label)}</h4></header><p class="area-intel-no-zone">${phase3Cell(card.context)}</p><div class="area-intel-metrics">${card.metrics.map(metric => `<div class="area-intel-metric"><span>${phase3Cell(metric.label)}</span><strong>${phase3Cell(metric.value)}</strong></div>`).join('')}</div></article>`).join('');
}
function renderAreaIntelligence() {
  const from=$('#areaIntelFrom')?.value,to=$('#areaIntelTo')?.value,table=$('#areaIntelligenceTable');if(!table)return;
  const areaChart=$('#areaRevenueChart'),zoneChart=$('#areaZoneRevenueChart'),packageChart=$('#packageRevenueChart'),basis=$('#areaIntelBasis');
  try {
    const referenceDate=new Date(),area=buildAreaIntelligence(state,{startDate:from,endDate:to},referenceDate),packages=buildPackageRevenue(state,{startDate:from,endDate:to},referenceDate);
    const namedAreas=area.rows.filter(row=>row.level==='area'&&row.billedAmount!==null).map(row=>({label:row.area.replace(/^Area:\s*/,''),value:row.billedAmount})).sort((a,b)=>b.value-a.value);
    const zones=area.rows.filter(row=>row.level==='zone'&&row.billedAmount!==null).map(row=>({label:`${row.parentArea.replace(/^(?:Area|Mohalla):\s*/,'')} · ${row.area.replace(/^Zone:\s*/, '')}`,value:row.billedAmount})).sort((a,b)=>b.value-a.value);
    areaChart.innerHTML=namedAreas.length?categoryBarsSvg(namedAreas,{title:`Service-month revenue by area, ${from} to ${to}`}):'<p class="empty-state">No saved priced bill snapshots for named areas in this range.</p>';
    zoneChart.innerHTML=zones.length?categoryBarsSvg(zones,{title:`Service-month revenue by zone, ${from} to ${to}`}):'<p class="empty-state">No saved priced bill snapshots for named zones in this range.</p>';
    packageChart.innerHTML=packages.rows.length?categoryBarsSvg(packages.rows.map(row=>({label:row.package,value:row.revenue})),{title:`Service-month revenue by recorded package, ${from} to ${to}`}):'<p class="empty-state">No positive priced bill snapshots in the selected service months.</p>';
    const bandwidthYield = buildZoneBandwidthYield(state, referenceDate, { speedMbpsFor: resolvePackageSpeedMbps, priceForMonth: applicablePriceForMonth });
    let areaRows = area.rows.map(row => {
      const bw = bandwidthYield.byId.get(row.id);
      return bw ? { ...row, subscribers: bw.subscribers, provisionedMbps: bw.provisionedMbps, avgSpeedMbps: bw.avgSpeedMbps, bandwidthRevenue: bw.monthlyRevenue, yieldPkrPerMbps: bw.yieldPkrPerMbps, unresolvedSpeedCount: bw.unresolvedSpeedCount }
        : { ...row, subscribers: 0, provisionedMbps: null, avgSpeedMbps: null, bandwidthRevenue: null, yieldPkrPerMbps: null, unresolvedSpeedCount: 0 };
    });
    if (areaSortKey) {
      areaRows.sort((a, b) => {
        let cmp = 0;
        if (areaSortKey === 'area') {
          cmp = (a.area || '').localeCompare(b.area || '');
        } else if (areaSortKey === 'totalCustomers') {
          cmp = (a.totalCustomers || 0) - (b.totalCustomers || 0);
        } else if (areaSortKey === 'activeCustomers') {
          const vA = a.activeCustomers === null ? -1 : a.activeCustomers;
          const vB = b.activeCustomers === null ? -1 : b.activeCustomers;
          cmp = vA - vB;
        } else if (areaSortKey === 'billedAmount') {
          const vA = a.billedAmount === null ? -1 : a.billedAmount;
          const vB = b.billedAmount === null ? -1 : b.billedAmount;
          cmp = vA - vB;
        } else if (areaSortKey === 'collectedAmount') {
          const vA = a.collectedAmount === null ? -1 : a.collectedAmount;
          const vB = b.collectedAmount === null ? -1 : b.collectedAmount;
          cmp = vA - vB;
        } else if (areaSortKey === 'outstanding') {
          const vA = a.outstanding === null ? -1 : a.outstanding;
          const vB = b.outstanding === null ? -1 : b.outstanding;
          cmp = vA - vB;
        } else if (areaSortKey === 'collectionRate') {
          const vA = a.collectionRate === null ? -1 : a.collectionRate;
          const vB = b.collectionRate === null ? -1 : b.collectionRate;
          cmp = vA - vB;
        } else if (areaSortKey === 'averageCustomerValue') {
          const vA = a.averageCustomerValue === null ? -1 : a.averageCustomerValue;
          const vB = b.averageCustomerValue === null ? -1 : b.averageCustomerValue;
          cmp = vA - vB;
        } else if (areaSortKey === 'expenses') {
          const vA = a.expenses === null ? -1 : a.expenses;
          const vB = b.expenses === null ? -1 : b.expenses;
          cmp = vA - vB;
        } else if (areaSortKey === 'estimatedProfit') {
          const vA = a.estimatedProfit === null ? -Infinity : a.estimatedProfit;
          const vB = b.estimatedProfit === null ? -Infinity : b.estimatedProfit;
          cmp = vA - vB;
        } else if (areaSortKey === 'provisionedMbps') {
          cmp = (a.provisionedMbps ?? -1) - (b.provisionedMbps ?? -1);
        } else if (areaSortKey === 'avgSpeedMbps') {
          cmp = (a.avgSpeedMbps ?? -1) - (b.avgSpeedMbps ?? -1);
        } else if (areaSortKey === 'yieldPkrPerMbps') {
          cmp = (a.yieldPkrPerMbps ?? -1) - (b.yieldPkrPerMbps ?? -1);
        }
        return areaSortAsc ? cmp : -cmp;
      });
    }

    if (areaSearchQuery.trim()) {
      const q = areaSearchQuery.trim().toLowerCase();
      areaRows = areaRows.filter(row => {
        const areaStr = (row.area || '').toLowerCase();
        const parentStr = (row.parentArea || '').toLowerCase();
        return areaStr.includes(q) || parentStr.includes(q);
      });
    }

    const countBadge = $('#areaIntelRowCount');
    if (countBadge) {
      if (areaSearchQuery.trim()) {
        countBadge.textContent = `Showing ${areaRows.length} of ${area.rows.length}`;
      } else {
        countBadge.textContent = `${area.rows.length} area/zone rows`;
      }
    }

    document.querySelectorAll('[data-sort-area]').forEach(th => {
      const key = th.dataset.sortArea;
      const indicator = th.querySelector('.sort-indicator');
      if (areaSortKey === key) {
        th.setAttribute('aria-sort', areaSortAsc ? 'ascending' : 'descending');
        if (indicator) indicator.textContent = areaSortAsc ? ' ↑' : ' ↓';
      } else {
        th.removeAttribute('aria-sort');
        if (indicator) indicator.textContent = '';
      }
    });

    table.innerHTML=areaRows.map(row=>{
      const label=`${row.area}`;const active=row.activeCustomers===null?'Not recorded for this historical date':String(row.activeCustomers);
      const amountOrMissing=value=>value===null?'Not recorded':formatAmount(value);
      return `<tr class="area-row-${phase3Cell(row.level)}"><th scope="row"><span class="location-summary-label location-summary-${phase3Cell(row.level)}" style="--summary-depth:${row.depth}"><span class="location-summary-type">${phase3Cell(row.level==='unassigned'?'Unassigned':row.level)}</span><span class="location-summary-value">${phase3Cell(label.replace(/^(?:Area|Mohalla|Zone):\s*/,''))}</span></span></th><td>${row.totalCustomers}</td><td title="${phase3Cell(row.activeCustomerSource)}">${phase3Cell(active)}</td><td>${phase3Cell(amountOrMissing(row.billedAmount))}</td><td>${phase3Cell(amountOrMissing(row.collectedAmount))}</td><td>${phase3Cell(amountOrMissing(row.outstanding))}</td><td>${row.collectionRate===null?'Not set':`${row.collectionRate}%`}</td><td>${phase3Cell(amountOrMissing(row.averageCustomerValue))}</td><td title="${phase3Cell(row.expensesSource)}">${phase3Cell(amountOrMissing(row.expenses))}</td><td title="${phase3Cell(row.estimatedProfitBasis)}">${phase3Cell(amountOrMissing(row.estimatedProfit))}</td><td${row.unresolvedSpeedCount > 0 ? ` title="${phase3Cell(t('zby_unresolved_title', null, { count: row.unresolvedSpeedCount }))}"` : ''}>${row.provisionedMbps === null ? '—' : `${row.provisionedMbps} Mbps`}</td><td>${row.avgSpeedMbps === null ? '—' : `${row.avgSpeedMbps} Mbps`}</td><td>${row.yieldPkrPerMbps === null ? '—' : phase3Cell(formatAmount(row.yieldPkrPerMbps))}</td></tr>`;
    }).join('');

    const intelCards = $('#areaIntelligenceCards'); if (intelCards) intelCards.innerHTML = renderAreaIntelligenceCardsHtml(areaRows);

    const emptyEl = $('#areaIntelligenceEmpty');
    if (emptyEl) {
      emptyEl.hidden = areaRows.length > 0;
      if (areaRows.length === 0 && areaSearchQuery.trim()) {
        emptyEl.innerHTML = `No areas or zones match "${phase3Cell(areaSearchQuery.trim())}". <button id="resetAreaIntelFiltersBtn" class="secondary-button btn-sm" type="button" style="margin-left: 8px;">Reset filter</button>`;
        $('#resetAreaIntelFiltersBtn')?.addEventListener('click', () => {
          const searchInp = $('#areaIntelSearch');
          if (searchInp) searchInp.value = '';
          areaSearchQuery = '';
          renderAreaIntelligence();
        });
      } else {
        emptyEl.textContent = 'No area / zone values or matching financial records are saved for this selection.';
      }
    }

    basis.textContent=`${from} to ${to}. ${area.basis.customers} ${area.basis.activeCustomers} ${area.basis.billing} ${area.basis.collection} ${area.basis.outstanding} ${area.basis.collectionRate} ${area.basis.averageCustomerValue} ${area.basis.expenses} ${area.basis.profit}${area.unallocatedExpenseCount?` ${area.unallocatedExpenseCount} expense record(s) in this range have no location tag.`:''} ${packages.basis}`;
  } catch(error) {
    table.replaceChildren();
    const intelCards = $('#areaIntelligenceCards'); if (intelCards) intelCards.replaceChildren();
    const emptyEl = $('#areaIntelligenceEmpty');
    if (emptyEl) {
      emptyEl.hidden=false;
      emptyEl.textContent=error.message;
    }
    for(const host of [areaChart,zoneChart,packageChart])host.innerHTML=`<p class="empty-state">${phase3Cell(error.message)}</p>`;
    basis.textContent='Select a valid date range to calculate the local area and package summaries.';
  }
}
// Plan 6 (Plan 1-100) — Owner daily/weekly collection digest.
// Render-only: every figure below comes from a source the app already
// computes (phase3 cash collection / outstanding, the Waada-queue
// tier rule via promiseDate, the suspense register summary). The
// digest builder itself computes nothing new; it only assembles and
// labels those figures, so the panel can never drift from its home
// screens on the same render. Buttons are bound once (dataset flag),
// because renderAnalytics runs on every Analytics visit.
let ownerDigestPeriod = 'daily';
let lastOwnerDigest = null;
let ownerDigestButtonsBound = false;
function renderOwnerDigest(period) {
  const bodyEl = $('#ownerDigestBody');
  if (!bodyEl) return;
  if (period) ownerDigestPeriod = period;
  const today = getWaadaTodayString();
  const range = ownerDigestPeriod === 'weekly' ? weeklyDigestRange(today) : dailyDigestRange(today);
  if (!range.valid) { bodyEl.innerHTML = ''; lastOwnerDigest = null; return; }
  const entries = paymentEntries(state).filter(({ payment }) => payment.date >= range.startDate && payment.date <= range.endDate);
  const allocations = calculatePaymentAllocations(state);
  let duesCustomers = 0;
  const waadaItems = [];
  for (const customer of state.customers ?? []) {
    if (customer.archived) continue;
    const outstanding = totalOutstandingFigures(customer, allocations).total;
    if (!(outstanding > 0)) continue;
    duesCustomers += 1;
    const promiseDate = typeof customer.promiseDate === 'string' ? customer.promiseDate.trim() : '';
    if (promiseDate && isValidWaadaDate(promiseDate) && promiseDate < today) {
      waadaItems.push({
        customerName: customer.name || customer.customerName || '—',
        promiseDate,
        amount: Number(customer.promiseAmount) > 0 ? Math.round(Number(customer.promiseAmount)) : Math.round(outstanding),
      });
    }
  }
  const suspenseEntries = loadSuspensePayments().filter((entry) => !entry.claimed);
  const suspense = suspenseSummary(loadSuspensePayments());
  const digest = buildOwnerDigest({
    period: ownerDigestPeriod,
    startDate: range.startDate,
    endDate: range.endDate,
    collections: {
      amount: entries.reduce((sum, { payment }) => sum + Number(payment.amount || 0), 0),
      count: entries.length,
      sourceScreen: 'Analytics cash collection',
    },
    dues: {
      amount: latestAnalyticsData && latestAnalyticsData.totalBills ? latestAnalyticsData.currentOutstanding : 0,
      customerCount: duesCustomers,
      sourceScreen: 'Analytics outstanding',
    },
    waadaBroken: {
      count: waadaItems.length,
      amount: waadaItems.reduce((sum, item) => sum + item.amount, 0),
      items: waadaItems,
      sourceScreen: 'Waada queue',
    },
    suspenseUnclaimed: {
      count: suspense.unclaimedCount,
      amount: suspense.unclaimedAmount,
      items: suspenseEntries.map((entry) => ({ suspenseId: entry.suspenseId, amount: entry.amount, ageDays: suspenseAgeDays(entry, today) })),
      sourceScreen: 'Suspense register',
    },
  });
  lastOwnerDigest = digest;
  bodyEl.innerHTML = digestHtml(digest);
  const dailyBtn = $('#ownerDigestDailyBtn');
  const weeklyBtn = $('#ownerDigestWeeklyBtn');
  if (dailyBtn) dailyBtn.setAttribute('aria-pressed', ownerDigestPeriod === 'daily' ? 'true' : 'false');
  if (weeklyBtn) weeklyBtn.setAttribute('aria-pressed', ownerDigestPeriod === 'weekly' ? 'true' : 'false');
  if (!ownerDigestButtonsBound) {
    ownerDigestButtonsBound = true;
    if (dailyBtn) dailyBtn.addEventListener('click', () => renderOwnerDigest('daily'));
    if (weeklyBtn) weeklyBtn.addEventListener('click', () => renderOwnerDigest('weekly'));
    const exportBtn = $('#ownerDigestExportBtn');
    if (exportBtn) exportBtn.addEventListener('click', () => {
      if (!lastOwnerDigest || !lastOwnerDigest.valid) return;
      downloadCsvFile(digestFilename(lastOwnerDigest), digestCsv(lastOwnerDigest));
    });
  }
}
// Plan 7 (Plan 1-100) — Receivables ageing by bill age.
// Render-only: bill-level outstanding figures come from the same
// allocation engine the billing register uses (balanceDueCents per
// bill month), grouped by the pure receivables-ageing module. It
// reads no Waada field, changes no bill/total/Waada record, and
// covers bill outstanding only — manual baqaya is not a bill, so
// it is not included here (the panel copy says so).
let lastReceivablesAgeing = null;
let receivablesAgeingExportBound = false;
function renderReceivablesAgeing() {
  const bodyEl = $('#receivablesAgeingBody');
  if (!bodyEl) return;
  const today = getWaadaTodayString();
  const asOfMonth = typeof today === 'string' && today.length >= 7 ? today.slice(0, 7) : '';
  const allocations = calculatePaymentAllocations(state);
  const entries = [];
  for (const customer of state.customers ?? []) {
    if (customer.archived) continue;
    const canon = canonicalMohalla(customer.mohalla || customer.area || '');
    for (const bill of customer.bills ?? []) {
      const summary = allocations.forMonth(customer.id, bill.month);
      const balanceDue = summary && summary.balanceDueCents > 0 ? summary.balanceDueCents / 100 : 0;
      if (!(balanceDue > 0)) continue;
      entries.push({
        customerId: customer.id,
        customerName: customer.name || customer.customerName || '—',
        mohallaKey: canon ? canon.key : undefined,
        mohallaLabel: canon ? canon.label : undefined,
        mohalla: customer.mohalla || customer.area || '',
        billMonth: bill.month,
        amount: Math.round(balanceDue),
      });
    }
  }
  const view = buildReceivablesAgeing(entries, asOfMonth);
  lastReceivablesAgeing = view.valid ? { view, entries } : null;
  bodyEl.innerHTML = view.valid ? ageingHtml(view) : '';
  if (!receivablesAgeingExportBound) {
    receivablesAgeingExportBound = true;
    const exportBtn = $('#receivablesAgeingExportBtn');
    if (exportBtn) exportBtn.addEventListener('click', () => {
      if (!lastReceivablesAgeing) return;
      downloadCsvFile(ageingFilename(lastReceivablesAgeing.view), ageingCsv(lastReceivablesAgeing.view, lastReceivablesAgeing.entries));
    });
  }
}
// Plan 8 (Plan 1-100) — Owner alerts inbox.
// Render-only: thresholds and cleared ids live in localStorage (UI
// state only). Clearing an alert never touches the underlying record,
// and restoring cleared alerts brings them back unchanged.
const ALERTS_INBOX_THRESHOLDS_KEY = 'alertsInboxThresholds';
const ALERTS_INBOX_CLEARED_KEY = 'alertsInboxCleared';
let alertsInboxBound = false;
function loadAlertsInboxThresholds() {
  try {
    const raw = localStorage.getItem(ALERTS_INBOX_THRESHOLDS_KEY);
    return raw ? normalizeAlertThresholds(JSON.parse(raw)) : { ...DEFAULT_ALERT_THRESHOLDS };
  } catch { return { ...DEFAULT_ALERT_THRESHOLDS }; }
}
function loadAlertsInboxCleared() {
  try {
    const parsed = JSON.parse(localStorage.getItem(ALERTS_INBOX_CLEARED_KEY) || '[]');
    return Array.isArray(parsed) ? parsed.filter((id) => typeof id === 'string') : [];
  } catch { return []; }
}
function saveAlertsInboxCleared(ids) {
  try { localStorage.setItem(ALERTS_INBOX_CLEARED_KEY, JSON.stringify(ids)); } catch {}
}
function saveAlertsInboxThresholds(thresholds) {
  try { localStorage.setItem(ALERTS_INBOX_THRESHOLDS_KEY, JSON.stringify(thresholds)); } catch {}
}
function renderAlertsInbox() {
  const bodyEl = $('#alertsInboxBody');
  if (!bodyEl) return;
  const today = getWaadaTodayString();
  const thresholds = loadAlertsInboxThresholds();
  const allocations = calculatePaymentAllocations(state);
  const waadaItems = [];
  const outstandingItems = [];
  for (const customer of state.customers ?? []) {
    if (customer.archived) continue;
    const outstanding = totalOutstandingFigures(customer, allocations).total;
    if (!(outstanding > 0)) continue;
    outstandingItems.push({ customerId: customer.id, customerName: customer.name || customer.customerName || '—', amount: Math.round(outstanding) });
    const promiseDate = typeof customer.promiseDate === 'string' ? customer.promiseDate.trim() : '';
    if (promiseDate && isValidWaadaDate(promiseDate) && promiseDate < today) {
      waadaItems.push({ customerId: customer.id, customerName: customer.name || customer.customerName || '—', promiseDate, amount: Number(customer.promiseAmount) > 0 ? Math.round(Number(customer.promiseAmount)) : Math.round(outstanding) });
    }
  }
  const suspenseItems = loadSuspensePayments().filter((entry) => !entry.claimed).map((entry) => ({ suspenseId: entry.suspenseId, amount: entry.amount, ageDays: suspenseAgeDays(entry, today) }));
  const view = buildAlertsInbox({ today, thresholds, waadaItems, suspenseItems, outstandingItems, clearedIds: loadAlertsInboxCleared() });
  bodyEl.innerHTML = view.valid ? alertsInboxHtml(view) : '<p class="empty-state">Alerts unavailable — the inbox needs a valid today date.</p>';
  const summaryEl = $('#alertsInboxSummary');
  if (summaryEl) summaryEl.textContent = alertsInboxSummaryText(view);
  const waadaInput = $('#alertsInboxWaadaDays');
  if (waadaInput) waadaInput.value = view.thresholds.waadaOverdueDays;
  const suspenseInput = $('#alertsInboxSuspenseDays');
  if (suspenseInput) suspenseInput.value = view.thresholds.suspenseUnclaimedDays;
  const outstandingInput = $('#alertsInboxLargeAmount');
  if (outstandingInput) outstandingInput.value = view.thresholds.largeOutstandingAmount;
  const restoreBtn = $('#alertsInboxRestoreBtn');
  if (restoreBtn) restoreBtn.hidden = !(view.valid && view.summary.clearedCount > 0);
  if (!alertsInboxBound) {
    alertsInboxBound = true;
    bodyEl.addEventListener('click', (event) => {
      const clearBtn = event.target.closest ? event.target.closest('.alerts-inbox-clear-btn') : null;
      if (clearBtn && clearBtn.dataset.alertId) {
        const ids = loadAlertsInboxCleared();
        if (!ids.includes(clearBtn.dataset.alertId)) ids.push(clearBtn.dataset.alertId);
        saveAlertsInboxCleared(ids);
        renderAlertsInbox();
        return;
      }
      const actionBtn = event.target.closest ? event.target.closest('.alerts-inbox-action-btn') : null;
      if (actionBtn) {
        if (actionBtn.dataset.alertAction === ALERT_TYPES.SUSPENSE_UNCLAIMED) {
          if (typeof suspensePaymentsModalController !== 'undefined' && suspensePaymentsModalController) suspensePaymentsModalController.open();
        } else {
          switchView('customers');
        }
      }
    });
    const saveBtn = $('#alertsInboxSaveThresholdsBtn');
    if (saveBtn) saveBtn.addEventListener('click', () => {
      saveAlertsInboxThresholds({
        waadaOverdueDays: Number($('#alertsInboxWaadaDays')?.value),
        suspenseUnclaimedDays: Number($('#alertsInboxSuspenseDays')?.value),
        largeOutstandingAmount: Number($('#alertsInboxLargeAmount')?.value),
      });
      renderAlertsInbox();
    });
    if (restoreBtn) restoreBtn.addEventListener('click', () => {
      saveAlertsInboxCleared([]);
      renderAlertsInbox();
    });
  }
}
// Plan 9 (Plan 1-100): collector performance panel — read-only.
// Today's route stops are the plan, today's recorded route
// outcomes are the visits, the promise register supplies
// promises, and today's payment ledger supplies cash (voided
// payments skipped by the module). Route visits and promises
// carry no collector name in storage yet, so they appear under
// "Unassigned" until a collector is recorded on the visit;
// shop-recorded payments show their shop. No payment,
// commission, or Waada record is changed here.
let lastCollectorPerformance = null;
let collectorPerformanceExportBound = false;
function renderCollectorPerformance() {
  const bodyEl = $('#collectorPerformanceBody');
  if (!bodyEl) return;
  const today = getWaadaTodayString();
  const routes = calculateFieldCollectionRoutes(state, { dateStr: today, storage: localStorage });
  const outcomes = getFieldRouteOutcomes(localStorage, today);
  const plannedVisits = (routes.stops || []).map((stop) => ({ customerId: stop.id }));
  const visits = Object.entries(outcomes || {}).map(([customerId, record]) => ({ customerId, outcome: record?.outcome }));
  let promises = [];
  try {
    const raw = localStorage.getItem('shahdara_collection_promises_v1');
    const list = raw ? JSON.parse(raw) : [];
    promises = (Array.isArray(list) ? list : []).map((entry) => ({
      customerId: entry.customerId,
      promisedDate: entry.promisedDate,
      status: entry.status,
      fulfilledAt: entry.fulfilledAt,
      fulfilledPaymentId: entry.fulfilledPaymentId,
    }));
  } catch {}
  const payments = paymentEntries(state)
    .filter(({ payment }) => payment.date === today)
    .map(({ payment }) => ({
      collector: resolveShopCollector(payment.method, payment.paidBy),
      amount: payment.amount,
      voided: payment.voided === true,
    }));
  const view = buildCollectorPerformance({ today, plannedVisits, visits, payments, promises });
  lastCollectorPerformance = view.valid ? { view } : null;
  bodyEl.innerHTML = view.valid ? collectorPerformanceHtml(view) : '<p class="empty-state">Collector performance unavailable — the view needs a valid today date.</p>';
  if (!collectorPerformanceExportBound) {
    collectorPerformanceExportBound = true;
    const exportBtn = $('#collectorPerformanceExportBtn');
    if (exportBtn) exportBtn.addEventListener('click', () => {
      if (!lastCollectorPerformance) return;
      downloadCsvFile(collectorPerformanceFilename(lastCollectorPerformance.view), collectorPerformanceCsv(lastCollectorPerformance.view));
    });
  }
}
// Plan 10 (Plan 1-100) — Month cash-flow snapshot.
// Render-only: collected comes from the payment-entries builder
// (receipt-date cash, voided receipts already skipped by that
// builder, as the owner digest uses it) and expenses from the dated
// expense records (as the P&L screen sums them for the same month).
// It changes no total and no expense rule; the projection is a
// run-rate estimate stated in plain words by the pure module.
let lastCashflowSnapshot = null;
let cashflowSnapshotExportBound = false;
function renderCashflowSnapshot() {
  const bodyEl = $('#cashflowSnapshotBody');
  if (!bodyEl) return;
  const today = getWaadaTodayString();
  const month = typeof today === 'string' && today.length >= 7 ? today.slice(0, 7) : '';
  const entries = paymentEntries(state).filter(({ payment }) => typeof payment.date === 'string' && payment.date.slice(0, 7) === month);
  const monthExpenses = (state.expenses ?? []).filter((row) => typeof row.date === 'string' && row.date.slice(0, 7) === month);
  const snapshot = buildCashflowSnapshot({
    month,
    asOfDate: today,
    collected: {
      amount: entries.reduce((sum, { payment }) => sum + Number(payment.amount || 0), 0),
      count: entries.length,
      sourceScreen: 'Analytics cash collection',
    },
    expenses: {
      amount: monthExpenses.reduce((sum, row) => sum + Number(row.amount || 0), 0),
      count: monthExpenses.length,
      items: monthExpenses.map((row) => ({ amount: row.amount, category: row.category })),
      sourceScreen: 'Expenses register',
    },
  });
  lastCashflowSnapshot = snapshot.valid ? snapshot : null;
  bodyEl.innerHTML = snapshot.valid ? cashflowSnapshotHtml(snapshot) : '<p class="empty-state">Cash-flow snapshot unavailable — the view needs a valid month and today date.</p>';
  if (!cashflowSnapshotExportBound) {
    cashflowSnapshotExportBound = true;
    const exportBtn = $('#cashflowSnapshotExportBtn');
    if (exportBtn) exportBtn.addEventListener('click', () => {
      if (!lastCashflowSnapshot) return;
      downloadCsvFile(cashflowSnapshotFilename(lastCashflowSnapshot), cashflowSnapshotCsv(lastCashflowSnapshot));
    });
  }
}
// Plan 11 (Plan 1-100) — Pre-due reminder queue.
// Read-only window list in Analytics: bills due within the next
// operator-set window (default 3 days), each with a bilingual draft.
// Sending opens the existing WhatsApp route with the draft prefilled
// and logs (time, channel) to a separate localStorage log; it changes
// no payment, Waada, or disconnection record. Bills with no stored
// due date are excluded, never given an invented one.
const PRE_DUE_WINDOW_KEY = 'preDueReminderWindowDays';
const PRE_DUE_SENT_LOG_KEY = 'shahdara_pre_due_sent_log_v1';
let preDueRemindersBound = false;
let lastPreDueQueue = null;
function loadPreDueWindowDays() {
  try {
    const raw = localStorage.getItem(PRE_DUE_WINDOW_KEY);
    return raw === null ? DEFAULT_PRE_DUE_WINDOW_DAYS : normalizePreDueWindowDays(Number(raw));
  } catch { return DEFAULT_PRE_DUE_WINDOW_DAYS; }
}
function loadPreDueSentLog() {
  try {
    const parsed = JSON.parse(localStorage.getItem(PRE_DUE_SENT_LOG_KEY) || '[]');
    return Array.isArray(parsed) ? parsed : [];
  } catch { return []; }
}
function savePreDueSentLog(log) {
  try { localStorage.setItem(PRE_DUE_SENT_LOG_KEY, JSON.stringify(log)); } catch {}
}
function renderPreDueReminders() {
  const bodyEl = $('#preDueRemindersBody');
  if (!bodyEl) return;
  const today = getWaadaTodayString();
  const windowDays = loadPreDueWindowDays();
  const allocations = calculatePaymentAllocations(state);
  const bills = [];
  for (const customer of state.customers ?? []) {
    if (customer.archived) continue;
    for (const bill of customer.bills ?? []) {
      const summary = allocations.forMonth(customer.id, bill.month);
      const balanceDue = summary && summary.balanceDueCents > 0 ? summary.balanceDueCents / 100 : 0;
      if (!(balanceDue > 0)) continue;
      bills.push({
        customerId: customer.id,
        customerName: customer.name || customer.customerName || '—',
        mohalla: customer.mohalla || customer.area || '',
        billId: bill.id,
        billMonth: bill.month,
        dueDate: typeof bill.dueDate === 'string' ? bill.dueDate : null,
        balanceDue: Math.round(balanceDue),
      });
    }
  }
  const queue = buildPreDueReminderQueue({ today, windowDays, bills });
  const sentLog = loadPreDueSentLog();
  lastPreDueQueue = queue.valid ? { queue, sentLog } : null;
  bodyEl.innerHTML = queue.valid ? preDueReminderHtml(queue, sentLog) : '<p class="empty-state">Pre-due reminder queue unavailable — the queue needs a valid today date.</p>';
  const summaryEl = $('#preDueRemindersSummary');
  if (summaryEl) summaryEl.textContent = preDueReminderSummaryText(queue);
  const windowInput = $('#preDueRemindersWindowDays');
  if (windowInput) windowInput.value = queue.windowDays;
  if (!preDueRemindersBound) {
    preDueRemindersBound = true;
    bodyEl.addEventListener('click', (event) => {
      const sendBtn = event.target.closest ? event.target.closest('.pre-due-send-btn') : null;
      if (!sendBtn || !sendBtn.dataset.customerId) return;
      const customer = (state.customers ?? []).find((c) => c.id === sendBtn.dataset.customerId);
      const row = lastPreDueQueue?.queue.rows.find((r) => r.customerId === sendBtn.dataset.customerId);
      if (!customer || !row) return;
      const pref = findContactPreference(loadContactPreferences(), row.customerId);
      if (pref && pref.doNotMessage) {
        sendBtn.disabled = true;
        sendBtn.textContent = 'Do not message';
        return;
      }
      const draftVariant = pref && pref.language === CONTACT_PREFERENCE_LANGUAGES.URDU ? PRE_DUE_DRAFT_VARIANTS.URDU : PRE_DUE_DRAFT_VARIANTS.ROMAN;
      const channelVariant = draftVariant === PRE_DUE_DRAFT_VARIANTS.URDU ? PAYMENT_CHANNEL_VARIANTS.URDU : PAYMENT_CHANNEL_VARIANTS.ROMAN;
      const wa = formatWhatsAppUrl(pref && pref.whatsappNumber ? pref.whatsappNumber : whatsappPhoneFor(customer), withPaymentInstructions(buildPreDueReminderDraft(row, draftVariant).text, findPaymentChannel(loadPaymentChannels(), row.customerId), channelVariant));
      if (!wa.validPhone || !wa.url) {
        sendBtn.disabled = true;
        sendBtn.textContent = 'No WhatsApp number';
        return;
      }
      window.open(wa.url, '_blank', 'noopener,noreferrer');
      savePreDueSentLog(logReminderSent(loadPreDueSentLog(), { customerId: row.customerId, sentAt: new Date().toISOString(), channel: 'whatsapp' }));
      renderPreDueReminders();
    });
    const saveBtn = $('#preDueRemindersSaveWindowBtn');
    if (saveBtn) saveBtn.addEventListener('click', () => {
      try { localStorage.setItem(PRE_DUE_WINDOW_KEY, String(normalizePreDueWindowDays(Number($('#preDueRemindersWindowDays')?.value)))); } catch {}
      renderPreDueReminders();
    });
    const exportBtn = $('#preDueRemindersExportBtn');
    if (exportBtn) exportBtn.addEventListener('click', () => {
      if (!lastPreDueQueue) return;
      downloadCsvFile(preDueReminderFilename(lastPreDueQueue.queue), preDueReminderCsv(lastPreDueQueue.queue, lastPreDueQueue.sentLog));
    });
  }
}
// Plan 12 (Plan 1-100) — Overdue escalation ladder panel. Overdue
// bills only (Plan 11 is the forward pre-due window); drafts only,
// plus a send log that lives apart from payment, Waada, and
// lifecycle records. Sending opens the existing WhatsApp route with
// the step draft prefilled and logs (step, time, channel) — it
// sends nothing automatically and changes no balance, promise, or
// service state.
const ESCALATION_THRESHOLDS_KEY = 'escalationLadderThresholds';
const ESCALATION_SENT_LOG_KEY = 'shahdara_escalation_sent_log_v1';
let escalationLadderBound = false;
let lastEscalationLadder = null;
function loadEscalationThresholds() {
  try {
    const raw = localStorage.getItem(ESCALATION_THRESHOLDS_KEY);
    return raw === null ? { ...DEFAULT_ESCALATION_THRESHOLDS } : normalizeEscalationThresholds(JSON.parse(raw));
  } catch { return { ...DEFAULT_ESCALATION_THRESHOLDS }; }
}
function loadEscalationSentLog() {
  try {
    const parsed = JSON.parse(localStorage.getItem(ESCALATION_SENT_LOG_KEY) || '[]');
    return Array.isArray(parsed) ? parsed : [];
  } catch { return []; }
}
function saveEscalationSentLog(log) {
  try { localStorage.setItem(ESCALATION_SENT_LOG_KEY, JSON.stringify(log)); } catch {}
}
function renderEscalationLadder() {
  const bodyEl = $('#escalationLadderBody');
  if (!bodyEl) return;
  const today = getWaadaTodayString();
  const thresholds = loadEscalationThresholds();
  const allocations = calculatePaymentAllocations(state);
  const bills = [];
  for (const customer of state.customers ?? []) {
    if (customer.archived) continue;
    for (const bill of customer.bills ?? []) {
      const summary = allocations.forMonth(customer.id, bill.month);
      const balanceDue = summary && summary.balanceDueCents > 0 ? summary.balanceDueCents / 100 : 0;
      if (!(balanceDue > 0)) continue;
      bills.push({
        customerId: customer.id,
        customerName: customer.name || customer.customerName || '—',
        mohalla: customer.mohalla || customer.area || '',
        billId: bill.id,
        billMonth: bill.month,
        dueDate: typeof bill.dueDate === 'string' ? bill.dueDate : null,
        balanceDue: Math.round(balanceDue),
      });
    }
  }
  // Plan 38: the ladder pauses for a bill until its extended date
  // passes. Paused bills are not on the ladder at all; bills past
  // their extended date return with the extended date as due date.
  const extensionResult = applyExtensionsToBills(bills, loadBillExtensions(), today);
  // Plan 62: the ladder chases only the undisputed portion while a
  // Plan 61 case is open. The split runs on the post-extension
  // list, so the Plan 38 pause rule is untouched, and it changes
  // only the balance figure — never a due date, a bill, a payment,
  // or a Waada record. A fully disputed bill drops to 0 and the
  // ladder already excludes zero-balance bills.
  const openCases = openDisputeCases(loadDisputeCases());
  const disputeTotalsByCustomer = new Map();
  for (const bill of extensionResult.bills) {
    if (!disputeTotalsByCustomer.has(bill.customerId)) {
      const totals = disputeTotalsForCustomer(extensionResult.bills, openCases, bill.customerId);
      if (totals) disputeTotalsByCustomer.set(bill.customerId, totals);
    }
  }
  const ladderAdjustment = adjustLadderBills(extensionResult.bills, openCases);
  const ladder = buildEscalationLadder({ today, thresholds, bills: ladderAdjustment.bills });
  if (ladder.valid) {
    for (const row of ladder.rows) {
      const totals = disputeTotalsByCustomer.get(row.customerId);
      if (totals && totals.disputedCents > 0) {
        row.disputeNote = `Dispute open: Rs. ${totals.disputed} of this customer's bills is disputed — this ladder chases only the undisputed Rs. ${totals.undisputed}.`;
      }
    }
  }
  const sentLog = loadEscalationSentLog();
  lastEscalationLadder = ladder.valid ? { ladder, sentLog, disputes: disputeTotalsByCustomer } : null;
  bodyEl.innerHTML = ladder.valid ? escalationHtml(ladder, sentLog) : '<p class="empty-state">Overdue escalation ladder unavailable — the ladder needs a valid today date.</p>';
  const summaryEl = $('#escalationLadderSummary');
  if (summaryEl) summaryEl.textContent = escalationSummaryText(ladder)
    + (extensionResult.counts.paused > 0 ? ` ${extensionResult.counts.paused} bill${extensionResult.counts.paused === 1 ? '' : 's'} paused by a bill extension until the extended date passes.` : '')
    + (ladderAdjustment.adjustedCount > 0 ? ` ${ladderAdjustment.adjustedCount} bill${ladderAdjustment.adjustedCount === 1 ? '' : 's'} chase only their undisputed portion while a dispute is open (Rs. ${ladderAdjustment.totalDisputedCents / 100} disputed held aside).` : '');
  const gentleInput = $('#escalationLadderGentleDays');
  if (gentleInput) gentleInput.value = ladder.thresholds.gentleDays;
  const firmInput = $('#escalationLadderFirmDays');
  if (firmInput) firmInput.value = ladder.thresholds.firmDays;
  const finalInput = $('#escalationLadderFinalDays');
  if (finalInput) finalInput.value = ladder.thresholds.finalDays;
  if (!escalationLadderBound) {
    escalationLadderBound = true;
    bodyEl.addEventListener('click', (event) => {
      const sendBtn = event.target.closest ? event.target.closest('.escalation-send-btn') : null;
      if (!sendBtn || !sendBtn.dataset.customerId) return;
      const customer = (state.customers ?? []).find((c) => c.id === sendBtn.dataset.customerId);
      const row = lastEscalationLadder?.ladder.rows.find((r) => r.customerId === sendBtn.dataset.customerId);
      if (!customer || !row) return;
      const pref = findContactPreference(loadContactPreferences(), row.customerId);
      if (pref && pref.doNotMessage) {
        sendBtn.disabled = true;
        sendBtn.textContent = 'Do not message';
        return;
      }
      const draftVariant = pref && pref.language === CONTACT_PREFERENCE_LANGUAGES.URDU ? ESCALATION_DRAFT_VARIANTS.URDU : ESCALATION_DRAFT_VARIANTS.ROMAN;
      const channelVariant = draftVariant === ESCALATION_DRAFT_VARIANTS.URDU ? PAYMENT_CHANNEL_VARIANTS.URDU : PAYMENT_CHANNEL_VARIANTS.ROMAN;
      // Plan 62: while a dispute is open, the sent draft chases only
      // the undisputed portion and says a dispute is open; otherwise
      // it is the ordinary ladder draft. The disputed amount is
      // never asked for, and no record changes.
      const disputeTotals = lastEscalationLadder?.disputes?.get(row.customerId);
      const disputedDraft = disputeTotals ? buildDisputedReminderDraft({
        customerName: row.customerName, step: row.step, dueDate: row.dueDate, daysOverdue: row.daysOverdue, split: disputeTotals,
      }, draftVariant === ESCALATION_DRAFT_VARIANTS.URDU ? DISPUTED_REMINDER_VARIANTS.URDU : DISPUTED_REMINDER_VARIANTS.ROMAN) : null;
      const draftText = disputedDraft ? disputedDraft.text : buildEscalationDraft(row, draftVariant).text;
      const wa = formatWhatsAppUrl(pref && pref.whatsappNumber ? pref.whatsappNumber : whatsappPhoneFor(customer), withPaymentInstructions(draftText, findPaymentChannel(loadPaymentChannels(), row.customerId), channelVariant));
      if (!wa.validPhone || !wa.url) {
        sendBtn.disabled = true;
        sendBtn.textContent = 'No WhatsApp number';
        return;
      }
      window.open(wa.url, '_blank', 'noopener,noreferrer');
      saveEscalationSentLog(logEscalationSent(loadEscalationSentLog(), { customerId: row.customerId, step: row.step, sentAt: new Date().toISOString(), channel: 'whatsapp' }));
      renderEscalationLadder();
    });
    const saveBtn = $('#escalationLadderSaveThresholdsBtn');
    if (saveBtn) saveBtn.addEventListener('click', () => {
      try {
        localStorage.setItem(ESCALATION_THRESHOLDS_KEY, JSON.stringify(normalizeEscalationThresholds({
          gentleDays: Number($('#escalationLadderGentleDays')?.value),
          firmDays: Number($('#escalationLadderFirmDays')?.value),
          finalDays: Number($('#escalationLadderFinalDays')?.value),
        })));
      } catch {}
      renderEscalationLadder();
    });
    const exportBtn = $('#escalationLadderExportBtn');
    if (exportBtn) exportBtn.addEventListener('click', () => {
      if (!lastEscalationLadder) return;
      downloadCsvFile(escalationFilename(lastEscalationLadder.ladder), escalationCsv(lastEscalationLadder.ladder, lastEscalationLadder.sentLog));
    });
  }
}
// Plan 13 (Plan 1-100) — Payment confirmation drafts panel. After a
// payment is recorded, the operator can send the customer a short
// bilingual confirmation (amount, date, remaining balance if any)
// through the existing WhatsApp route. The panel lists today's
// recorded payments only, so the remaining balance shown is the
// bill's current balance after the payments recorded so far today.
// Drafts only, plus a send log that lives apart from payment,
// receipt-delivery (Plan 5), and Waada records: sending a
// confirmation never marks a receipt sent and never clears or
// changes a Waada. Voided payments correctly have no draft and are
// counted in the summary, never listed.
const PAYMENT_CONFIRMATION_SENT_LOG_KEY = 'shahdara_payment_confirmation_sent_log_v1';
let paymentConfirmationBound = false;
let lastPaymentConfirmation = null;
function loadPaymentConfirmationSentLog() {
  try {
    const parsed = JSON.parse(localStorage.getItem(PAYMENT_CONFIRMATION_SENT_LOG_KEY) || '[]');
    return Array.isArray(parsed) ? parsed : [];
  } catch { return []; }
}
function savePaymentConfirmationSentLog(log) {
  try { localStorage.setItem(PAYMENT_CONFIRMATION_SENT_LOG_KEY, JSON.stringify(log)); } catch {}
}
function renderPaymentConfirmation() {
  const bodyEl = $('#paymentConfirmationBody');
  if (!bodyEl) return;
  const today = getWaadaTodayString();
  const allocations = calculatePaymentAllocations(state);
  const payments = [];
  for (const customer of state.customers ?? []) {
    if (customer.archived) continue;
    for (const bill of customer.bills ?? []) {
      const summary = allocations.forMonth(customer.id, bill.month);
      const balanceDue = summary && summary.balanceDueCents > 0 ? summary.balanceDueCents / 100 : 0;
      for (const p of bill.payments ?? []) {
        if (p.date !== today) continue;
        payments.push({
          ...p,
          customerId: customer.id,
          customerName: customer.name || customer.customerName || '—',
          mohalla: customer.mohalla || customer.area || '',
          remainingBalance: Math.round(balanceDue),
        });
      }
    }
  }
  const list = buildPaymentConfirmationList({ payments });
  const sentLog = loadPaymentConfirmationSentLog();
  lastPaymentConfirmation = { list, sentLog, today };
  bodyEl.innerHTML = paymentConfirmationHtml(list, sentLog);
  const summaryEl = $('#paymentConfirmationSummary');
  if (summaryEl) summaryEl.textContent = paymentConfirmationSummaryText(list);
  if (!paymentConfirmationBound) {
    paymentConfirmationBound = true;
    bodyEl.addEventListener('click', (event) => {
      const sendBtn = event.target.closest ? event.target.closest('.payment-confirmation-send-btn') : null;
      if (!sendBtn || !sendBtn.dataset.paymentId) return;
      const row = lastPaymentConfirmation?.list.rows.find((r) => r.paymentId === sendBtn.dataset.paymentId);
      const customer = (state.customers ?? []).find((c) => c.id === row?.customerId);
      if (!customer || !row) return;
      const pref = findContactPreference(loadContactPreferences(), row.customerId);
      if (pref && pref.doNotMessage) {
        sendBtn.disabled = true;
        sendBtn.textContent = 'Do not message';
        return;
      }
      const draftText = pref && pref.language === CONTACT_PREFERENCE_LANGUAGES.URDU && row.draftUrdu ? row.draftUrdu : row.draft;
      const channelVariant = pref && pref.language === CONTACT_PREFERENCE_LANGUAGES.URDU ? PAYMENT_CHANNEL_VARIANTS.URDU : PAYMENT_CHANNEL_VARIANTS.ROMAN;
      const wa = formatWhatsAppUrl(pref && pref.whatsappNumber ? pref.whatsappNumber : whatsappPhoneFor(customer), withPaymentInstructions(draftText, findPaymentChannel(loadPaymentChannels(), row.customerId), channelVariant));
      if (!wa.validPhone || !wa.url) {
        sendBtn.disabled = true;
        sendBtn.textContent = 'No WhatsApp number';
        return;
      }
      window.open(wa.url, '_blank', 'noopener,noreferrer');
      savePaymentConfirmationSentLog(logConfirmationSent(loadPaymentConfirmationSentLog(), { paymentId: row.paymentId, customerId: row.customerId, sentAt: new Date().toISOString(), channel: 'whatsapp' }));
      renderPaymentConfirmation();
    });
    const exportBtn = $('#paymentConfirmationExportBtn');
    if (exportBtn) exportBtn.addEventListener('click', () => {
      if (!lastPaymentConfirmation) return;
      downloadCsvFile(paymentConfirmationFilename(lastPaymentConfirmation.today), paymentConfirmationCsv(lastPaymentConfirmation.list, lastPaymentConfirmation.sentLog));
    });
  }
}
const BROADCAST_TEMPLATES_KEY = 'shahdara_broadcast_templates_v1';
const BROADCAST_SENT_LOG_KEY = 'shahdara_broadcast_sent_log_v1';
const BROADCAST_SELECTION_KEY = 'shahdara_broadcast_selection_v1';
let mohallaBroadcastBound = false;
let lastMohallaBroadcast = null;
function loadBroadcastTemplates() {
  try {
    const parsed = JSON.parse(localStorage.getItem(BROADCAST_TEMPLATES_KEY) || '{}');
    return normalizeBroadcastTemplates(parsed && typeof parsed === 'object' ? parsed : {});
  } catch { return normalizeBroadcastTemplates({}); }
}
function saveBroadcastTemplates(templates) {
  try { localStorage.setItem(BROADCAST_TEMPLATES_KEY, JSON.stringify(templates)); } catch {}
}
function loadBroadcastSentLog() {
  try {
    const parsed = JSON.parse(localStorage.getItem(BROADCAST_SENT_LOG_KEY) || '[]');
    return Array.isArray(parsed) ? parsed : [];
  } catch { return []; }
}
function saveBroadcastSentLog(log) {
  try { localStorage.setItem(BROADCAST_SENT_LOG_KEY, JSON.stringify(log)); } catch {}
}
function loadBroadcastSelection() {
  try {
    const parsed = JSON.parse(localStorage.getItem(BROADCAST_SELECTION_KEY) || '[]');
    return Array.isArray(parsed) ? parsed.filter((k) => typeof k === 'string') : [];
  } catch { return []; }
}
function saveBroadcastSelection(keys) {
  try { localStorage.setItem(BROADCAST_SELECTION_KEY, JSON.stringify(keys)); } catch {}
}
function renderMohallaBroadcast() {
  const bodyEl = $('#mohallaBroadcastBody');
  if (!bodyEl) return;
  const templates = loadBroadcastTemplates();
  const kindEl = $('#mohallaBroadcastKind');
  const variantEl = $('#mohallaBroadcastVariant');
  const kind = kindEl?.value && Object.values(BROADCAST_TEMPLATE_KINDS).includes(kindEl.value) ? kindEl.value : BROADCAST_TEMPLATE_KINDS.MAINTENANCE;
  const variant = variantEl?.value === BROADCAST_DRAFT_VARIANTS.URDU ? BROADCAST_DRAFT_VARIANTS.URDU : BROADCAST_DRAFT_VARIANTS.ROMAN;
  const romanEl = $('#mohallaBroadcastTemplateRoman');
  const urduEl = $('#mohallaBroadcastTemplateUrdu');
  if (romanEl && document.activeElement !== romanEl) romanEl.value = templates[kind].roman;
  if (urduEl && document.activeElement !== urduEl) urduEl.value = templates[kind].urdu;
  const options = buildBroadcastMohallaOptions({ customers: state.customers ?? [] });
  const savedSelection = loadBroadcastSelection();
  const mohallasEl = $('#mohallaBroadcastMohallas');
  if (mohallasEl) {
    mohallasEl.innerHTML = options.map((opt) => `<label style="font-size: 12px;"><input type="checkbox" class="mohalla-broadcast-checkbox" value="${opt.key}"${savedSelection.includes(opt.key) ? ' checked' : ''}> ${opt.label}</label>`).join('');
  }
  const readSelection = () => [...document.querySelectorAll('.mohalla-broadcast-checkbox:checked')].map((box) => box.value);
  const prepareDraft = () => {
    const selection = readSelection();
    saveBroadcastSelection(selection);
    const draft = buildBroadcastDraft({
      kind, variant, templates: loadBroadcastTemplates(),
      detail: $('#mohallaBroadcastDetail')?.value ?? '',
      selection: selection.map((key) => options.find((opt) => opt.key === key)?.label ?? key),
      customers: state.customers ?? [],
    });
    lastMohallaBroadcast = draft ? { draft, sentLog: loadBroadcastSentLog() } : null;
    const summaryEl = $('#mohallaBroadcastSummary');
    if (summaryEl) summaryEl.textContent = draft ? broadcastSummaryText(draft) : 'No mohalla selected — no draft prepared.';
    bodyEl.innerHTML = draft ? broadcastHtml(draft, loadBroadcastSentLog()) : '<p class="empty-state">Pick at least one mohalla and press Prepare draft.</p>';
  };
  if (lastMohallaBroadcast) {
    bodyEl.innerHTML = broadcastHtml(lastMohallaBroadcast.draft, loadBroadcastSentLog());
    const summaryEl = $('#mohallaBroadcastSummary');
    if (summaryEl) summaryEl.textContent = broadcastSummaryText(lastMohallaBroadcast.draft);
  } else if (!bodyEl.innerHTML) {
    bodyEl.innerHTML = '<p class="empty-state">Pick at least one mohalla and press Prepare draft.</p>';
  }
  if (!mohallaBroadcastBound) {
    mohallaBroadcastBound = true;
    $('#mohallaBroadcastPrepareBtn')?.addEventListener('click', prepareDraft);
    mohallasEl?.addEventListener('change', () => saveBroadcastSelection(readSelection()));
    $('#mohallaBroadcastKind')?.addEventListener('change', () => {
      const t = loadBroadcastTemplates();
      const k = $('#mohallaBroadcastKind').value;
      if ($('#mohallaBroadcastTemplateRoman')) $('#mohallaBroadcastTemplateRoman').value = t[k].roman;
      if ($('#mohallaBroadcastTemplateUrdu')) $('#mohallaBroadcastTemplateUrdu').value = t[k].urdu;
    });
    $('#mohallaBroadcastSaveTemplateBtn')?.addEventListener('click', () => {
      const k = $('#mohallaBroadcastKind')?.value ?? BROADCAST_TEMPLATE_KINDS.MAINTENANCE;
      const current = loadBroadcastTemplates();
      current[k] = {
        roman: $('#mohallaBroadcastTemplateRoman')?.value ?? '',
        urdu: $('#mohallaBroadcastTemplateUrdu')?.value ?? '',
      };
      saveBroadcastTemplates(normalizeBroadcastTemplates(current));
      renderMohallaBroadcast();
    });
    $('#mohallaBroadcastSelectAllBtn')?.addEventListener('click', () => {
      document.querySelectorAll('.mohalla-broadcast-checkbox').forEach((box) => { box.checked = true; });
    });
    $('#mohallaBroadcastClearBtn')?.addEventListener('click', () => {
      document.querySelectorAll('.mohalla-broadcast-checkbox').forEach((box) => { box.checked = false; });
    });
    bodyEl.addEventListener('click', (event) => {
      const sendBtn = event.target.closest ? event.target.closest('.mohalla-broadcast-send-btn') : null;
      if (!sendBtn || !sendBtn.dataset.mohallaKey || !lastMohallaBroadcast) return;
      const key = sendBtn.dataset.mohallaKey;
      const mohalla = lastMohallaBroadcast.draft.mohallas.find((m) => m.key === key);
      if (!mohalla) return;
      window.open(broadcastWhatsAppUrl(lastMohallaBroadcast.draft.text), '_blank', 'noopener,noreferrer');
      saveBroadcastSentLog(logBroadcastSent(loadBroadcastSentLog(), { mohallas: [mohalla.label], sentAt: new Date().toISOString(), channel: 'whatsapp', kind: lastMohallaBroadcast.draft.kind }));
      bodyEl.innerHTML = broadcastHtml(lastMohallaBroadcast.draft, loadBroadcastSentLog());
    });
    $('#mohallaBroadcastExportBtn')?.addEventListener('click', () => {
      if (!lastMohallaBroadcast) return;
      downloadCsvFile(broadcastFilename(new Date().toISOString().slice(0, 10)), broadcastCsv(lastMohallaBroadcast.draft, loadBroadcastSentLog()));
    });
  }
}
// Plan 15 (Plan 1-100) — Customer contact preferences panel. One
// saved choice per customer: preferred WhatsApp number, preferred
// message language (Urdu script or Roman Urdu), and a do-not-message
// flag with a reason. Preferences live in their own localStorage
// store, apart from every payment, Waada and balance record, and
// they affect ONLY Plans 11–14 drafts: the three per-customer send
// buttons above resolve the preferred number and language and
// refuse a do-not-message send, and the broadcast audience helper
// lists opted-out customers as skipped. Changing a preference here
// changes no billing, collection or lifecycle figure.
const CONTACT_PREFERENCES_KEY = 'shahdara_contact_preferences_v1';
