// Build one customer's status reply from this profile's own
// open cases: the Plan 21 ticket log (joined rows, so the
// mohalla comes from the customer), the Plan 22 outage grouping
// (only an open outage linked to a ticket is named), and the
// Plan 50 change-request queue. Resolved and closed tickets are
// never included — the post-resolution confirmation (Plan 25)
// covers those. This draft changes no ticket or request record.
function statusReplyForCustomer(customer, variant) {
  const tickets = ticketLogJoinedRows().filter((row) => String(row.customerId) === String(customer.id));
  const outages = loadOutageGrouping();
  const requests = loadChangeRequests().filter((row) => String(row.customerId) === String(customer.id));
  return buildStatusReply({
    customerId: customer.id,
    customerName: customer.name || customer.customerName,
    tickets,
    outages,
    requests,
    variant,
  });
}
// Build one customer's info card from this profile's own
// figures: current package and monthly price resolved through
// the Plan 34 price history (revisions keyed by catalogue id,
// the customer's package by its label, so each side passes its
// own key), the Plan 36 billing cycle and the next bill month's
// due date, connection status, expiry date, and the support
// contact. A kept Plan 46 preview for a different package is
// shown only as a "change noted" line — the current package
// stays current until the change is applied through the Edit
// form. This card applies nothing and changes no record.
function infoCardForCustomer(customer, variant) {
  const plan = BILL_PACKAGES.find((entry) => entry.label === customer.packageSpeed)
    || BILL_PACKAGES.find((entry) => entry.id === customer.packageSpeed)
    || null;
  const price = priceOnDate(loadPriceHistory(), plan ? plan.id : customer.packageSpeed, localDate(), customer.monthlySellingAmount);
  const cycleChoice = findBillingCycleChoice(loadBillingCycleChoices(), customer.id);
  const today = localDate();
  const [year, month] = today.slice(0, 7).split('-').map(Number);
  const nextMonth = month === 12 ? `${year + 1}-01` : `${year}-${String(month + 1).padStart(2, '0')}`;
  const keptPreview = findPackageChangePreview(loadPackageChangePreviews(), customer.id);
  let supportContact = '';
  try { supportContact = getDigitalPaymentsSettings()?.ownerPhone || ''; } catch {}
  return buildInfoCard({
    customerId: customer.id,
    customerName: customer.name || customer.customerName,
    package: customer.packageSpeed,
    monthlyPrice: price,
    cycleDueDay: cycleChoice ? cycleChoice.dueDay : DEFAULT_BILL_DUE_DAY,
    cycleIsDefault: !cycleChoice,
    nextDueDate: dueDateForBillMonth(cycleChoice, nextMonth),
    connectionStatus: manualServiceStatusBareLabel(customer.serviceStatus),
    expiryDate: customer.expiryDate,
    supportContact,
    pendingChange: keptPreview && keptPreview.proposedPackage !== customer.packageSpeed ? keptPreview : null,
    variant,
  });
}
// Build one customer's mini-slip from this profile's own ledger:
// every payment across the customer's bills (voided rows kept so
// the module can mark them VOID), plus the current outstanding
// from the shared figures helper. No payment is created, edited,
// or voided here; the module only reads caller-supplied rows.
function paymentSlipForCustomer(customer, variant, count) {
  const allocations = calculatePaymentAllocations(state);
  const outstanding = totalOutstandingFigures(customer, allocations).total;
  const payments = [];
  for (const bill of customer.bills ?? []) {
    for (const payment of bill.payments ?? []) {
      payments.push({
        date: payment.date,
        amount: payment.amount,
        channel: payment.method,
        voided: payment.voided === true,
      });
    }
  }
  return buildPaymentSlip({
    customerId: customer.id,
    customerName: customer.name || customer.customerName,
    payments,
    count,
    balance: outstanding,
    variant,
  });
}
// Build one customer's balance reply from this profile's own
// figures: total outstanding from the shared figures helper, the
// earliest due date among bills that still carry a balance, the
// latest non-voided payment, and that customer's open Plan 61
// cases (Plan 62's split is not recomputed here — the module
// shows the undisputed balance from those open cases only).
function balanceReplyForCustomer(customer, variant) {
  const allocations = calculatePaymentAllocations(state);
  const outstanding = totalOutstandingFigures(customer, allocations).total;
  let nextDueDate = null;
  for (const bill of customer.bills ?? []) {
    const summary = allocations.forMonth(customer.id, bill.month);
    if (summary && summary.balanceDueCents > 0 && bill.dueDate) {
      const valid = validBalanceReplyDate(bill.dueDate);
      if (valid && (!nextDueDate || valid < nextDueDate)) nextDueDate = valid;
    }
  }
  let lastPayment = null;
  for (const bill of customer.bills ?? []) {
    for (const payment of bill.payments ?? []) {
      if (payment.voided === true) continue;
      const date = validBalanceReplyDate(payment.date);
      const amount = Number(payment.amount);
      if (!date || !Number.isFinite(amount) || amount <= 0) continue;
      if (!lastPayment || date >= lastPayment.date) lastPayment = { amount, date };
    }
  }
  const openDisputes = openDisputeCases(loadDisputeCases()).filter((entry) => entry.customerId === customer.id);
  return buildBalanceReply({
    customerId: customer.id,
    customerName: customer.name || customer.customerName,
    outstanding,
    dueDate: nextDueDate,
    lastPayment,
    openDisputes,
    variant,
  });
}
let disputeLettersBound = false;
function loadDisputeLetterSentLog() {
  try {
    const parsed = JSON.parse(localStorage.getItem(DISPUTE_LETTERS_SENT_KEY) || '[]');
    return Array.isArray(parsed) ? parsed : [];
  } catch { return []; }
}
function saveDisputeLetterSentLog(list) {
  try { localStorage.setItem(DISPUTE_LETTERS_SENT_KEY, JSON.stringify(Array.isArray(list) ? list : [])); } catch {}
}
function disputeLetterForCase(caseId) {
  const cases = loadDisputeCases();
  const caseRecord = cases.find((entry) => entry.id === caseId) ?? null;
  if (!caseRecord) return null;
  const resolution = findResolution(loadDisputeResolutions(), caseId);
  const status = letterStatus(caseRecord, resolution);
  if (status !== 'ready') return { status, caseRecord, resolution: null, letter: null };
  const variant = normalizeLetterVariant($('#disputeLetterVariant')?.value ?? '');
  const billTotalRaw = ($('#disputeLetterBillTotal')?.value ?? '').trim();
  const paymentsRaw = ($('#disputeLetterPayments')?.value ?? '').trim();
  const letter = buildOutcomeLetter({
    caseRecord,
    resolution,
    billTotal: billTotalRaw === '' ? null : billTotalRaw,
    paymentsReceived: paymentsRaw === '' ? null : paymentsRaw,
    variant,
  });
  return { status, caseRecord, resolution, letter };
}
function renderDisputeLetters() {
  const bodyEl = $('#disputeLetterBody');
  if (!bodyEl) return;
  const cases = loadDisputeCases();
  const names = {};
  for (const c of state.customers ?? []) names[c.id] = c.name || c.customerName || c.id;
  const caseEl = $('#disputeLetterCase');
  if (caseEl && document.activeElement !== caseEl) {
    caseEl.innerHTML = cases.map((entry) => `<option value="${escapeHtml(entry.id)}">${escapeHtml(entry.id)} — ${escapeHtml(names[entry.customerId] || entry.customerId)} — ${escapeHtml(entry.billId)} (${escapeHtml(DISPUTE_STATUS_LABELS[entry.status])})</option>`).join('')
      || '<option value="">No cases yet</option>';
  }
  const picked = disputeLetterForCase(caseEl?.value ?? '');
  const draftEl = $('#disputeLetterDraft');
  const sendBtn = $('#disputeLetterSendBtn');
  const pref = picked?.caseRecord ? findContactPreference(loadContactPreferences(), picked.caseRecord.customerId) : null;
  if (!picked || !picked.caseRecord) {
    if (draftEl) draftEl.innerHTML = '<p style="font-size: 12px;">Pick a case to see its outcome letter.</p>';
    if (sendBtn) { sendBtn.disabled = true; sendBtn.textContent = 'Send letter via WhatsApp'; }
  } else if (picked.status === 'not_resolved') {
    if (draftEl) draftEl.innerHTML = '<p style="font-size: 12px;">Outcome letters are offered only for resolved cases. This case is still open.</p>';
    if (sendBtn) { sendBtn.disabled = true; sendBtn.textContent = 'Send letter via WhatsApp'; }
  } else if (picked.status === 'awaiting') {
    if (draftEl) draftEl.innerHTML = '<p style="font-size: 12px;">This resolved case is still awaiting its letter — record its finding and outcome in the resolution panel above first. Nothing is invented for it.</p>';
    if (sendBtn) { sendBtn.disabled = true; sendBtn.textContent = 'Send letter via WhatsApp'; }
  } else {
    const sends = findLetterSends(loadDisputeLetterSentLog(), picked.caseRecord.id);
    if (draftEl) draftEl.innerHTML = letterHtml(picked.letter, { draftText: picked.letter.text, sends });
    if (sendBtn) {
      sendBtn.disabled = Boolean(pref && pref.doNotMessage);
      sendBtn.textContent = pref && pref.doNotMessage ? 'Do not message' : (sends.length > 0 ? 'Re-send letter' : 'Send letter via WhatsApp');
    }
  }
  const sentEl = $('#disputeLetterSent');
  if (sentEl) sentEl.textContent = picked?.caseRecord ? letterSentText(findLetterSends(loadDisputeLetterSentLog(), picked.caseRecord.id)) : '';
  const month = $('#disputeLetterMonth')?.value || '';
  const view = buildMonthlyDisputeView(cases, loadDisputeResolutions(), month);
  const viewEl = $('#disputeLetterMonthly');
  if (viewEl) viewEl.innerHTML = monthlyDisputeHtml(view);
  const summaryEl = $('#disputeLetterSummary');
  if (summaryEl) summaryEl.textContent = monthlyDisputeViewText(view);
  if (!disputeLettersBound) {
    disputeLettersBound = true;
    $('#disputeLetterCase')?.addEventListener('change', () => renderDisputeLetters());
    $('#disputeLetterVariant')?.addEventListener('change', () => renderDisputeLetters());
    $('#disputeLetterShowBtn')?.addEventListener('click', () => renderDisputeLetters());
    $('#disputeLetterMonth')?.addEventListener('change', () => renderDisputeLetters());
    $('#disputeLetterSendBtn')?.addEventListener('click', (event) => {
      const button = event.currentTarget;
      const pickedNow = disputeLetterForCase($('#disputeLetterCase')?.value ?? '');
      if (!pickedNow?.letter) { button.disabled = true; return; }
      const prefNow = findContactPreference(loadContactPreferences(), pickedNow.caseRecord.customerId);
      if (prefNow && prefNow.doNotMessage) { button.disabled = true; button.textContent = 'Do not message'; return; }
      const customer = (state.customers ?? []).find((c) => c.id === pickedNow.caseRecord.customerId) ?? null;
      const wa = formatWhatsAppUrl(prefNow && prefNow.whatsappNumber ? prefNow.whatsappNumber : (customer ? whatsappPhoneFor(customer) : ''), pickedNow.letter.text);
      if (!wa.validPhone || !wa.url) { button.disabled = true; button.textContent = 'No WhatsApp number'; return; }
      window.open(wa.url, '_blank', 'noopener,noreferrer');
      saveDisputeLetterSentLog(logLetterSent(loadDisputeLetterSentLog(), { caseId: pickedNow.caseRecord.id, customerId: pickedNow.caseRecord.customerId, sentAt: new Date().toISOString(), channel: 'whatsapp', variant: pickedNow.letter.variant }));
      toast('Outcome letter sent. Sending it changes no bill, payment, or case record.');
      renderDisputeLetters();
    });
    $('#disputeLetterExportBtn')?.addEventListener('click', () => {
      const exportMonth = $('#disputeLetterMonth')?.value || '';
      downloadCsvFile(monthlyDisputeFilename(exportMonth), monthlyDisputeCsv(buildMonthlyDisputeView(loadDisputeCases(), loadDisputeResolutions(), exportMonth)));
    });
  }
}
// Plan 66 (Plan 1-100) — Co-pilot "Pucho" box. The box gathers the
// app's existing records into the pure module's caller-supplied
// shape and renders its answers. Asking changes nothing: no bill,
// payment, Waada, ticket, or customer record is written here, and
// every action button only reminds the operator to confirm the
// action on its existing source screen.
let puchoBound = false;
let puchoLastQuestion = '';
function puchoData() {
  const today = localDate();
  const allocations = calculatePaymentAllocations(state);
  const customers = (state.customers ?? []).filter((c) => !c.archived);
  const nameOf = (c) => c.name || c.customerName || c.id;
  const mohallaOf = (c) => c.mohalla || c.area || '';
  const dues = [];
  const expiries = [];
  const waada = [];
  const payments = [];
  for (const customer of customers) {
    const outstanding = totalOutstandingFigures(customer, allocations).totalCents;
    if (outstanding > 0) dues.push({ customerId: customer.id, customerName: nameOf(customer), mohalla: mohallaOf(customer), outstandingCents: outstanding });
    if (customer.expiryDate) expiries.push({ customerId: customer.id, customerName: nameOf(customer), mohalla: mohallaOf(customer), expiryDate: customer.expiryDate });
    if (customer.promiseDate) waada.push({ customerId: customer.id, customerName: nameOf(customer), mohalla: mohallaOf(customer), promiseDate: customer.promiseDate, promiseAmountCents: customer.promiseAmount === null || customer.promiseAmount === undefined || customer.promiseAmount === '' ? null : Math.round(Number(customer.promiseAmount) * 100) });
    for (const bill of customer.bills ?? []) {
      for (const payment of bill.payments ?? []) {
        if (!payment || !Number.isFinite(Number(payment.amount))) continue;
        payments.push({ date: payment.date, amountCents: Math.round(Number(payment.amount) * 100), voided: payment.voided === true, customerName: nameOf(customer) });
      }
    }
  }
  const suspense = loadSuspensePayments().filter((entry) => !entry.claimed).map((entry) => ({ id: entry.suspenseId, amountCents: Math.round(Number(entry.amount) * 100), date: entry.date, claimed: false }));
  const tickets = ticketLogJoinedRows().map((ticket) => ({ id: ticket.id, customerId: ticket.customerId, customerName: ticket.customerName, mohalla: ticket.mohalla, category: ticket.category, priority: ticket.priority, status: ticket.status, reportedDate: ticket.reportedDate }));
  const repeatFlags = currentRepeatFaultFlags().map((flag) => ({ customerId: flag.customerId, customerName: flag.customerName || flag.customerId, mohalla: flag.mohalla, category: flag.category, count: flag.count, ticketIds: flag.ticketIds ?? (flag.tickets ?? []).map((ticket) => ticket.id) }));
  const atRisk = (buildAtRiskList({ ...buildAtRiskInputs(), thresholds: loadAtRiskThresholds() }).rows ?? []).map((row) => ({ customerId: row.customerId, customerName: row.customerName, mohalla: row.mohalla, signals: (row.signals ?? []).map((signal) => (signal.detail ? `${signal.label}: ${signal.detail}` : (signal.label || ''))).filter(Boolean) }));
  const disputeBills = [];
  for (const customer of customers) {
    for (const bill of customer.bills ?? []) {
      const summary = allocations.forMonth(customer.id, bill.month);
      const balanceDue = summary && summary.balanceDueCents > 0 ? summary.balanceDueCents / 100 : 0;
      if (!(balanceDue > 0)) continue;
      disputeBills.push({ customerId: customer.id, customerName: nameOf(customer), mohalla: mohallaOf(customer), billId: bill.id, billMonth: bill.month, total: Math.round(balanceDue) });
    }
  }
  const disputes = splitBillList(disputeBills, openDisputeCases(loadDisputeCases())).map((row) => ({ caseId: (row.caseIds ?? [])[0] ?? '', customerId: row.customerId, customerName: row.customerName, mohalla: row.mohalla, billId: row.billId, billMonth: row.billMonth, totalCents: row.totalCents, disputedCents: row.disputedCents, status: 'open' }));
  return { today, dues, expiries, waada, suspense, tickets, repeatFlags, atRisk, disputes, payments };
}
function renderPuchoBox() {
  const bodyEl = $('#puchoAnswerBody');
  if (!bodyEl) return;
  const catalogueEl = $('#puchoCatalogue');
  if (catalogueEl) catalogueEl.innerHTML = puchoCatalogueHtml();
  if (puchoLastQuestion) {
    bodyEl.innerHTML = puchoHtml(answerPucho(puchoLastQuestion, puchoData()));
  } else {
    bodyEl.innerHTML = '<p style="font-size: 12px;">Ask a question above, or open the morning queue.</p>';
  }
  if (!puchoBound) {
    puchoBound = true;
    $('#puchoAskBtn')?.addEventListener('click', () => {
      puchoLastQuestion = $('#puchoQuestion')?.value ?? '';
      renderPuchoBox();
    });
    $('#puchoQuestion')?.addEventListener('keydown', (event) => {
      if (event.key === 'Enter') {
        event.preventDefault();
        puchoLastQuestion = event.currentTarget.value;
        renderPuchoBox();
      }
    });
    $('#puchoQueueBtn')?.addEventListener('click', () => {
      puchoLastQuestion = 'morning queue';
      const input = $('#puchoQuestion');
      if (input) input.value = 'morning queue';
      renderPuchoBox();
    });
    $('#puchoQueueExportBtn')?.addEventListener('click', () => {
      downloadCsvFile(morningQueueFilename(), morningQueueCsv(buildMorningQueue(puchoData())));
    });
    bodyEl.addEventListener('click', (event) => {
      const button = event.target.closest?.('.pucho-action-btn');
      if (!button) return;
      toast(`"${button.dataset.puchoAction}" — asking changes nothing. Confirm this action on the ${button.dataset.puchoSource} screen first.`);
    });
  }
}
// Plan 67 (Plan 1-100) — Month-end close checklist. One ticked
// record per month with the same six ordered steps; ticking,
// waiving, closing, or reopening a step never posts, corrects,
// or closes any other record. A closed month reopens only with
// an owner-recorded reason, which is also written into the
// Plan 31 operator action audit log. This is the close routine,
// not the owner pack (Plan R), not the balance proof (Plan 68),
// and not the SISP-130 pre-flight wizard, which is neither read
// nor written here.
const MONTH_CLOSE_KEY = 'shahdara_month_close_v1';
function loadMonthClose() {
  try {
    const parsed = JSON.parse(localStorage.getItem(MONTH_CLOSE_KEY) || '[]');
    return normalizeMonthCloseList(Array.isArray(parsed) ? parsed : []);
  } catch { return []; }
}
function saveMonthClose(list) {
  try { localStorage.setItem(MONTH_CLOSE_KEY, JSON.stringify(normalizeMonthCloseList(list))); } catch {}
}
let monthCloseBound = false;
function renderMonthClose() {
  const bodyEl = $('#monthCloseBody');
  if (!bodyEl) return;
  const monthEl = $('#monthCloseMonth');
  if (monthEl && !monthEl.value) monthEl.value = localDate().slice(0, 7);
  const month = monthEl?.value ?? localDate().slice(0, 7);
  const list = loadMonthClose();
  const record = validCloseMonth(month) ? findMonthClose(list, month) : null;
  const stepEl = $('#monthCloseStep');
  if (stepEl && document.activeElement !== stepEl) {
    stepEl.innerHTML = CLOSE_STEPS.map((step) => `<option value="${escapeHtml(step.id)}">${escapeHtml(step.label)}</option>`).join('');
  }
  const summaryEl = $('#monthCloseSummary');
  if (!record) {
    bodyEl.innerHTML = '<p style="font-size: 12px;">No close checklist started for this month yet.</p>';
    if (summaryEl) summaryEl.textContent = '';
  } else {
    bodyEl.innerHTML = monthCloseHtml(record);
    if (summaryEl) summaryEl.textContent = monthCloseSummaryText(record);
  }
  const closeBtn = $('#monthCloseCloseBtn');
  if (closeBtn) closeBtn.disabled = !record || record.status === 'closed';
  const reopenBtn = $('#monthCloseReopenBtn');
  if (reopenBtn) reopenBtn.disabled = !record || record.status !== 'closed';
  if (!monthCloseBound) {
    monthCloseBound = true;
    $('#monthCloseMonth')?.addEventListener('change', () => renderMonthClose());
    $('#monthCloseStartBtn')?.addEventListener('click', () => {
      const picked = $('#monthCloseMonth')?.value ?? '';
      if (!validCloseMonth(picked)) { toast('Pick a valid month first.'); return; }
      if (findMonthClose(loadMonthClose(), picked)) { toast('A checklist for this month already exists.'); return; }
      saveMonthClose([...loadMonthClose(), blankMonthClose(picked)]);
      toast('Close checklist started. Ticking a step changes no other record.');
      renderMonthClose();
    });
    const stepAction = (action) => {
      const picked = $('#monthCloseMonth')?.value ?? '';
      const stepId = $('#monthCloseStep')?.value ?? '';
      const date = $('#monthCloseDate')?.value ?? '';
      const by = ($('#monthCloseBy')?.value ?? '').trim();
      const reason = ($('#monthCloseReason')?.value ?? '').trim();
      const before = loadMonthClose();
      let next = before;
      if (action === 'tick') next = tickCloseStep(next, { month: picked, stepId, date, by });
      else if (action === 'waive') next = waiveCloseStep(next, { month: picked, stepId, date, by, reason });
      else next = untickCloseStep(next, { month: picked, stepId });
      if (JSON.stringify(next) === JSON.stringify(before)) {
        toast(action === 'waive'
          ? 'Waiving needs a date, a name, and a reason — and an open month.'
          : 'Ticking needs a date and a name — and an open month.');
        return;
      }
      saveMonthClose(next);
      renderMonthClose();
    };
    $('#monthCloseTickBtn')?.addEventListener('click', () => stepAction('tick'));
    $('#monthCloseWaiveBtn')?.addEventListener('click', () => stepAction('waive'));
    $('#monthCloseUntickBtn')?.addEventListener('click', () => stepAction('untick'));
    $('#monthCloseCloseBtn')?.addEventListener('click', () => {
      const picked = $('#monthCloseMonth')?.value ?? '';
      const by = ($('#monthCloseBy')?.value ?? '').trim();
      const recordNow = findMonthClose(loadMonthClose(), picked);
      if (!recordNow) { toast('Start the checklist for this month first.'); return; }
      const readiness = closeReadiness(recordNow);
      if (!readiness.canClose) { toast(`Cannot close yet — still pending: ${readiness.missing.join(', ')}.`); return; }
      saveMonthClose(closeMonth(loadMonthClose(), { month: picked, date: localDate(), by }));
      toast('Month marked closed. Closing ticks nothing and changes no other record.');
      renderMonthClose();
    });
    $('#monthCloseReopenBtn')?.addEventListener('click', () => {
      const picked = $('#monthCloseMonth')?.value ?? '';
      const by = ($('#monthCloseBy')?.value ?? '').trim();
      const reason = ($('#monthCloseReason')?.value ?? '').trim();
      if (!reason) { toast('Reopening needs an owner-recorded reason.'); return; }
      const before = loadMonthClose();
      const next = reopenMonth(before, { month: picked, reason, by, date: localDate() });
      if (JSON.stringify(next) === JSON.stringify(before)) { toast('Only a closed month can be reopened, with a reason, by, and date.'); return; }
      saveMonthClose(next);
      recordAudit('month_close_reopened', { recordRef: picked, detail: reason, by });
      toast('Month reopened. The reason is recorded in the audit log.');
      renderMonthClose();
    });
    $('#monthCloseRemoveBtn')?.addEventListener('click', () => {
      const picked = $('#monthCloseMonth')?.value ?? '';
      saveMonthClose(removeMonthClose(loadMonthClose(), picked));
      renderMonthClose();
    });
    $('#monthCloseExportBtn')?.addEventListener('click', () => {
      const picked = $('#monthCloseMonth')?.value ?? '';
      downloadCsvFile(monthCloseFilename(picked), monthCloseCsv(loadMonthClose()));
    });
  }
}
// Plan 68: balance roll-forward, read-only. The proof view only:
// opening (previous arrears from the allocation engine, Plan P) plus
// this month's bills raised, minus cash received, minus concessions
// and waivers applied through their existing paths, equals the
// closing balance. A customer with no bill in the month carries the
// opening balance forward unchanged. Nothing here posts, corrects,
// or rewrites any figure; a row that does not reconcile shows its
// difference plainly.
let rollForwardBound = false;
function rollForwardRowsForMonth(month) {
  return (state.customers ?? []).map((customer) => {
    const opening = arrearsAndAdvance(customer, month).previousArrears;
    const bills = (customer.bills ?? []).filter((bill) => bill && bill.month === month);
    const charges = [];
    const payments = [];
    const concessions = [];
    let reported = opening;
    for (const bill of bills) {
      const breakdown = billClarityBreakdown(customer, bill);
      if (!breakdown) continue;
      const billId = bill.id ?? bill.month;
      const push = (list, label, amount) => {
        if (typeof amount === 'number' && amount > 0) list.push({ sourceId: String(billId), label, amount });
      };
      push(charges, 'Monthly package', breakdown.packageAmount);
      push(charges, 'Kist (installments this month)', breakdown.kistAmount);
      push(charges, 'Late fee', breakdown.lateFeeAmount);
      push(charges, 'Shifting fee', breakdown.shiftingFeeAmount);
      push(payments, 'Cash received this month', breakdown.cashPaid);
      push(concessions, 'Concession', breakdown.concessionAmount);
      push(concessions, 'Deposit offset', breakdown.depositOffsetAmount);
      push(concessions, 'Referral credit', breakdown.referralCreditAmount);
      push(concessions, 'Feeder host credit', breakdown.feederHostCreditAmount);
      push(concessions, 'Credit transfer in', breakdown.creditTransferInAmount);
      push(concessions, 'Bad-debt write-off', breakdown.badDebtWriteOffAmount);
      push(concessions, 'Advance consumed', breakdown.advanceConsumed);
      push(concessions, 'Payment discount', breakdown.discountApplied);
      reported += (breakdown.netBalance ?? 0) - (breakdown.previousArrears ?? 0);
    }
    return buildCustomerRollForward({
      customerId: customer.id,
      customerName: customer.name || customer.id,
      mohalla: customer.mohalla || '',
      month,
      opening,
      charges,
      payments,
      concessions,
      reportedClosing: reported,
    });
  }).filter((row) => row !== null);
}
function renderRollForward() {
  const bodyEl = $('#rollForwardBody');
  if (!bodyEl) return;
  const monthEl = $('#rollForwardMonth');
  if (monthEl && !monthEl.value) monthEl.value = localDate().slice(0, 7);
  const month = monthEl?.value ?? localDate().slice(0, 7);
  const customerEl = $('#rollForwardCustomer');
  if (customerEl && document.activeElement !== customerEl) {
    const current = customerEl.value ?? '';
    customerEl.innerHTML = `<option value="">All customers</option>` + (state.customers ?? []).map((c) => `<option value="${escapeHtml(c.id)}">${escapeHtml(c.name || c.id)}</option>`).join('');
    if ((state.customers ?? []).some((c) => String(c.id) === String(current))) customerEl.value = current;
  }
  const summaryEl = $('#rollForwardSummary');
  if (!validRollMonth(month)) {
    bodyEl.innerHTML = '<p style="font-size: 12px;">Pick a valid month to see the roll-forward.</p>';
    if (summaryEl) summaryEl.textContent = '';
  } else {
    const rows = rollForwardRowsForMonth(month);
    const totals = buildRollForwardTotals(rows);
    const picked = customerEl?.value ?? '';
    if (picked) {
      const row = rows.find((item) => String(item.customerId) === String(picked));
      bodyEl.innerHTML = row ? rollForwardHtml(row) : '<p style="font-size: 12px;">No roll-forward row for this customer.</p>';
      if (summaryEl) summaryEl.textContent = row ? rollForwardSummaryText(row) : '';
    } else {
      bodyEl.innerHTML = rollForwardTableHtml(rows);
      if (summaryEl) summaryEl.textContent = rollForwardSummaryText({ ...totals, month });
    }
  }
  if (!rollForwardBound) {
    rollForwardBound = true;
    $('#rollForwardMonth')?.addEventListener('change', () => renderRollForward());
    $('#rollForwardCustomer')?.addEventListener('change', () => renderRollForward());
    $('#rollForwardExportBtn')?.addEventListener('click', () => {
      const pickedMonth = $('#rollForwardMonth')?.value ?? localDate().slice(0, 7);
      if (!validRollMonth(pickedMonth)) { toast('Pick a valid month first.'); return; }
      const rows = rollForwardRowsForMonth(pickedMonth);
      downloadCsvFile(rollForwardFilename(pickedMonth), rollForwardCsv(rows, buildRollForwardTotals(rows)));
    });
  }
}
// Plan 69: pre-close unreconciled items sweep, read-only. One list
// before the Plan 67 checklist is ticked: unclaimed suspense (all
// currently open items, oldest first), unmatched or disputed wallet
// entries for the picked month, open payment claims (Plan 63), and
// days of the picked month with physical cash but no handover
// record. Wallet rows are deduped by transaction id: a duplicate-TID
// group already listed as disputed is not also listed as an
// unmatched ledger row, so the same money is never counted twice.
// The sweep holds no copy of its own — clearing an item from its
// own screen removes it from the next sweep — and a month marked
// closed with items still open carries them as carried-forward
// exceptions. Nothing here resolves, creates, or changes a record.
let precloseSweepBound = false;
function precloseSweepForMonth(month) {
  const today = localDate();
  const suspenseItems = loadSuspensePayments().filter((entry) => entry && !entry.claimed).map((entry) => ({
    id: entry.suspenseId,
    label: entry.suspenseId || 'Suspense',
    detail: [entry.wallet, entry.tid ? `TID ${entry.tid}` : '', entry.senderName].filter(Boolean).join(' · '),
    amount: entry.amount,
    ageDays: suspenseAgeDays(entry, today),
    date: entry.date,
  }));
  let inboxItems = [];
  try {
    const parsed = JSON.parse(localStorage.getItem('easypaisaInbox.items') || '[]');
    inboxItems = Array.isArray(parsed) ? parsed : [];
  } catch { inboxItems = []; }
  const report = buildWalletReconciliation(state.customers, month, loadShopSettlements());
  const reconView = buildWalletReconView({
    report,
    customers: state.customers,
    inboxItems,
    suspenseEntries: loadSuspensePayments(),
    settings: getDigitalPaymentsSettings(),
  });
  const buckets = reconView.buckets || {};
  const unmatchedRows = [
    ...(buckets.unmatched?.rows ?? []),
    ...(buckets['inbox-review']?.rows ?? []),
    ...(buckets['inbox-unrecorded']?.rows ?? []),
  ];
  const seenTids = new Set(unmatchedRows.map((row) => String(row.tid || '').trim().toUpperCase()).filter(Boolean));
  const walletItems = [
    ...unmatchedRows,
    ...(buckets.disputed?.rows ?? []).filter((row) => !String(row.tid || '').trim() || !seenTids.has(String(row.tid).trim().toUpperCase())),
  ].map((row, index) => ({
    id: row.paymentId || row.tid || `${row.source || 'wallet'}-${row.date || ''}-${index}`,
    bucket: row.bucket,
    label: row.customerName || row.tid || 'Wallet entry',
    detail: [row.method, row.tid ? `TID ${row.tid}` : '', row.detail].filter(Boolean).join(' · '),
    amount: row.amount,
    date: row.date,
  }));
  const claims = openPaymentClaims(loadPaymentClaims()).map((claim) => ({
    id: claim.id,
    label: `${claim.id} · ${claim.customerName || claim.customerId}`,
    detail: [claim.channel, claim.reference ? `Ref ${claim.reference}` : '', claim.outcome].filter(Boolean).join(' · '),
    amount: claim.amount,
    date: claim.dateClaimed,
    closed: false,
  }));
  const paymentDates = new Set();
  for (const customer of state.customers ?? []) {
    if (customer.archived) continue;
    for (const bill of customer.bills ?? []) {
      if (!bill) continue;
      for (const payment of bill.payments ?? []) {
        if (!payment || payment.voided === true) continue;
        const date = typeof payment.date === 'string' ? payment.date.slice(0, 10) : '';
        if (date.startsWith(month)) paymentDates.add(date);
      }
    }
  }
  const handovers = [];
  for (const date of [...paymentDates].sort()) {
    let expectedCash = 0;
    try { expectedCash = calculateCollectorCashExpected(state, date, 'all').expectedCash || 0; } catch { expectedCash = 0; }
    if (!(expectedCash > 0)) continue;
    const recorded = getDailyCashHandovers(typeof localStorage !== 'undefined' ? localStorage : null, date).length > 0;
    if (recorded) continue;
    handovers.push({
      date,
      label: `Day ${date}`,
      detail: `Expected cash ${formatAmount(expectedCash)}, no handover recorded`,
      amount: expectedCash,
      handoverRecorded: false,
    });
  }
  return buildPrecloseSweep({
    month,
    suspenseItems,
    walletItems,
    claims,
    handovers,
    monthClose: findMonthClose(loadMonthClose(), month),
  });
}
function renderPrecloseSweep() {
  const bodyEl = $('#precloseSweepBody');
  if (!bodyEl) return;
  const monthEl = $('#precloseSweepMonth');
  if (monthEl && !monthEl.value) monthEl.value = localDate().slice(0, 7);
  const month = monthEl?.value ?? localDate().slice(0, 7);
  const summaryEl = $('#precloseSweepSummary');
  if (!validSweepMonth(month)) {
    bodyEl.innerHTML = '<p style="font-size: 12px;">Pick a valid month to run the pre-close sweep.</p>';
    if (summaryEl) summaryEl.textContent = '';
  } else {
    const sweep = precloseSweepForMonth(month);
    bodyEl.innerHTML = precloseSweepHtml(sweep);
    if (summaryEl) summaryEl.textContent = precloseSweepSummaryText(sweep);
  }
  if (!precloseSweepBound) {
    precloseSweepBound = true;
    $('#precloseSweepMonth')?.addEventListener('change', () => renderPrecloseSweep());
    $('#precloseSweepExportBtn')?.addEventListener('click', () => {
      const pickedMonth = $('#precloseSweepMonth')?.value ?? localDate().slice(0, 7);
      if (!validSweepMonth(pickedMonth)) { toast('Pick a valid month first.'); return; }
      downloadCsvFile(precloseSweepFilename(pickedMonth), precloseSweepCsv(precloseSweepForMonth(pickedMonth)));
    });
    $('#precloseSweepOpenSuspenseBtn')?.addEventListener('click', () => {
      if (typeof suspensePaymentsModalController !== 'undefined' && suspensePaymentsModalController?.open) suspensePaymentsModalController.open();
      else toast('Suspense register is not available here.');
    });
    $('#precloseSweepOpenWalletBtn')?.addEventListener('click', () => {
      const pickedMonth = $('#precloseSweepMonth')?.value ?? localDate().slice(0, 7);
      if (walletLedgerModalController?.open) walletLedgerModalController.open({ month: pickedMonth });
      else toast('Wallet ledger is not available here.');
    });
    $('#precloseSweepOpenClaimsBtn')?.addEventListener('click', () => {
      const target = document.getElementById('paymentClaimsBody');
      if (target) target.scrollIntoView({ behavior: 'smooth', block: 'start' });
      else toast('Payment-claim check is not available here.');
    });
    $('#precloseSweepOpenHandoverBtn')?.addEventListener('click', () => {
      if (dailyClosingModalController?.open) dailyClosingModalController.open();
      else toast('Daily closing is not available here.');
    });
  }
}
// Plan 70: frozen month-end balance snapshot, read-only. Taken only
// when the Plan 67 checklist records the month as closed, from the
// Plan 68 roll-forward closing balances plus the month's collections
// and expense total. One snapshot per month, taken once, never
// overwritten or edited in place: later payments, corrections, or
// concessions appear in the next month's roll-forward, never by
// rewriting a frozen month. Snapshots also ride with the Plan 32
// export pack as a snapshots section. Opening, comparing, or
// exporting a snapshot never changes any live record.
const MONTH_SNAPSHOTS_KEY = 'shahdara_month_snapshots_v1';
function loadMonthSnapshots() {
  try {
    const parsed = JSON.parse(localStorage.getItem(MONTH_SNAPSHOTS_KEY) || '[]');
    return normalizeSnapshotList(parsed);
  } catch { return []; }
}
function saveMonthSnapshots(list) {
  try { localStorage.setItem(MONTH_SNAPSHOTS_KEY, JSON.stringify(normalizeSnapshotList(list))); } catch {}
}
let monthSnapshotsBound = false;
function renderMonthSnapshots() {
  const bodyEl = $('#monthSnapshotBody');
  if (!bodyEl) return;
  const monthEl = $('#monthSnapshotMonth');
  if (monthEl && !monthEl.value) monthEl.value = localDate().slice(0, 7);
  const month = monthEl?.value ?? localDate().slice(0, 7);
  const summaryEl = $('#monthSnapshotSummary');
  const selectEl = $('#monthSnapshotSelect');
  const earlierEl = $('#monthSnapshotEarlier');
  const laterEl = $('#monthSnapshotLater');
  const list = loadMonthSnapshots();
  const options = list.map((snap) => `<option value="${escapeHtml(snap.month)}">${escapeHtml(snap.month)} — frozen ${escapeHtml(snap.closeDate)}</option>`).join('');
  if (selectEl && document.activeElement !== selectEl) {
    const current = selectEl.value ?? '';
    selectEl.innerHTML = `<option value="">Pick a snapshot</option>${options}`;
    if (list.some((snap) => snap.month === current)) selectEl.value = current;
  }
  if (earlierEl && document.activeElement !== earlierEl) {
    const current = earlierEl.value ?? '';
    earlierEl.innerHTML = `<option value="">Earlier month</option>${options}`;
    if (list.some((snap) => snap.month === current)) earlierEl.value = current;
  }
  if (laterEl && document.activeElement !== laterEl) {
    const current = laterEl.value ?? '';
    laterEl.innerHTML = `<option value="">Later month</option>${options}`;
    if (list.some((snap) => snap.month === current)) laterEl.value = current;
  }
  const picked = selectEl?.value ?? '';
  const earlier = earlierEl?.value ?? '';
  const later = laterEl?.value ?? '';
  if (!validSnapshotMonth(month)) {
    bodyEl.innerHTML = '<p style="font-size: 12px;">Pick a valid month to take or view a snapshot.</p>';
    if (summaryEl) summaryEl.textContent = '';
  } else if (earlier && later) {
    const comparison = compareSnapshots(findSnapshot(list, earlier), findSnapshot(list, later));
    bodyEl.innerHTML = comparison ? compareSnapshotsHtml(comparison) : '<p style="font-size: 12px;">Pick two stored snapshots to compare them.</p>';
    if (summaryEl) summaryEl.textContent = comparison ? compareSnapshotsSummaryText(comparison) : '';
  } else if (picked) {
    const snap = findSnapshot(list, picked);
    bodyEl.innerHTML = snap ? snapshotHtml(snap) : '<p style="font-size: 12px;">No snapshot stored for that month.</p>';
    if (summaryEl) summaryEl.textContent = snap ? snapshotSummaryText(snap) : '';
  } else {
    const existing = findSnapshot(list, month);
    bodyEl.innerHTML = existing
      ? snapshotHtml(existing)
      : '<p style="font-size: 12px;">No snapshot stored for this month yet. Close the month on the Plan 67 checklist first, then take its snapshot — it freezes once and is never rewritten.</p>';
    if (summaryEl) summaryEl.textContent = existing ? snapshotSummaryText(existing) : '';
  }
  if (!monthSnapshotsBound) {
    monthSnapshotsBound = true;
    $('#monthSnapshotMonth')?.addEventListener('change', () => renderMonthSnapshots());
    $('#monthSnapshotSelect')?.addEventListener('change', () => renderMonthSnapshots());
    $('#monthSnapshotEarlier')?.addEventListener('change', () => renderMonthSnapshots());
    $('#monthSnapshotLater')?.addEventListener('change', () => renderMonthSnapshots());
    $('#monthSnapshotTakeBtn')?.addEventListener('click', () => {
      const pickedMonth = $('#monthSnapshotMonth')?.value ?? localDate().slice(0, 7);
      if (!validSnapshotMonth(pickedMonth)) { toast('Pick a valid month first.'); return; }
      const closeRecord = findMonthClose(loadMonthClose(), pickedMonth);
      if (!closeRecord || closeRecord.status !== 'closed') { toast('Close the month on the month-end checklist first — a snapshot is taken only for a closed month.'); return; }
      const rows = rollForwardRowsForMonth(pickedMonth);
      const unusable = rows.filter((row) => row.computedCents === null);
      if (unusable.length) { toast(`Cannot freeze ${pickedMonth}: ${unusable.map((row) => row.customerName).join(', ')} have no usable closing balance. Fix the roll-forward first.`); return; }
      const monthExpenses = (state.expenses ?? []).filter((row) => typeof row.date === 'string' && row.date.slice(0, 7) === pickedMonth);
      const badExpense = monthExpenses.find((row) => typeof row.amount !== 'number' || !Number.isFinite(row.amount) || row.amount < 0);
      if (badExpense) { toast(`Cannot freeze ${pickedMonth}: an expense row has no usable amount. Fix it first.`); return; }
      const before = loadMonthSnapshots();
      const after = takeSnapshot(before, {
        month: pickedMonth,
        closeDate: closeRecord.closedDate,
        closedBy: closeRecord.closedBy,
        customers: rows.map((row) => ({ customerId: row.customerId, customerName: row.customerName, mohalla: row.mohalla, closing: row.computedClosing })),
        collections: rows.reduce((total, row) => total + (row.paymentsCents ?? 0), 0) / 100,
        expenses: monthExpenses.reduce((total, row) => total + row.amount, 0),
        monthClose: closeRecord,
      });
      if (after.length === before.length) { toast(`A snapshot for ${pickedMonth} already exists — frozen months are never re-frozen.`); return; }
      saveMonthSnapshots(after);
      toast(`Snapshot for ${pickedMonth} frozen at close.`);
      renderMonthSnapshots();
    });
    $('#monthSnapshotExportBtn')?.addEventListener('click', () => {
      const picked = $('#monthSnapshotSelect')?.value ?? $('#monthSnapshotMonth')?.value ?? '';
      const snap = findSnapshot(loadMonthSnapshots(), picked);
      if (!snap) { toast('Pick a stored snapshot first.'); return; }
      downloadCsvFile(snapshotFilename(picked), snapshotCsv(snap));
    });
    $('#monthSnapshotCompareExportBtn')?.addEventListener('click', () => {
      const comparison = compareSnapshots(findSnapshot(loadMonthSnapshots(), $('#monthSnapshotEarlier')?.value ?? ''), findSnapshot(loadMonthSnapshots(), $('#monthSnapshotLater')?.value ?? ''));
      if (!comparison) { toast('Pick two stored snapshots first.'); return; }
      downloadCsvFile(`month-snapshot-compare-${comparison.earlierMonth}-to-${comparison.laterMonth}.csv`, compareSnapshotsCsv(comparison));
    });
    $('#monthSnapshotRemoveBtn')?.addEventListener('click', () => {
      const picked = $('#monthSnapshotSelect')?.value ?? $('#monthSnapshotMonth')?.value ?? '';
      if (!findSnapshot(loadMonthSnapshots(), picked)) { toast('Pick a stored snapshot first.'); return; }
      saveMonthSnapshots(removeSnapshot(loadMonthSnapshots(), picked));
      toast(`Snapshot for ${picked} removed.`);
      renderMonthSnapshots();
    });
  }
}
// Plan 71: annual owner summary, composition only. One read-only year
// view from the twelve monthly figures: collections and expenses from
// each month's frozen snapshot (Plan 70) when one exists, new
// activations, departures, and churn from that month's Plan 60 summary,
// and a snapshot flag per month. A month with no frozen snapshot is
// flagged incomplete, never estimated, and its money figures stay
// unrecorded for that month; composing never changes any monthly pack
// or live record.
let annualSummaryBound = false;
function renderAnnualSummary() {
  const bodyEl = $('#annualSummaryBody');
  if (!bodyEl) return;
  const yearEl = $('#annualSummaryYear');
  if (yearEl && !yearEl.value) yearEl.value = localDate().slice(0, 4);
  const year = yearEl?.value ?? localDate().slice(0, 4);
  const snapshots = loadMonthSnapshots();
  const customers = churnSummaryCustomers();
  const rows = monthsOfYear(year).map((month) => {
    const snap = findSnapshot(snapshots, month);
    const churn = buildMonthlyChurnSummary({ month, customers, atRisk: [] });
    return {
      month,
      collections: snap ? snap.collectionsCents / 100 : null,
      expenses: snap ? snap.expensesCents / 100 : null,
      newCustomers: churn ? churn.newCustomers : null,
      departed: churn ? churn.departed : null,
      customersStart: churn ? churn.start : null,
      customersEnd: churn ? churn.end : null,
      churnRate: churn ? churn.churnRate : null,
      snapshotClosed: !!snap,
    };
  });
  const view = buildAnnualSummary({ year, months: rows });
  bodyEl.innerHTML = view ? annualSummaryHtml(view) : '<p style="font-size: 12px;">Pick a valid year to see the annual summary.</p>';
  const summaryEl = $('#annualSummarySummary');
  if (summaryEl) summaryEl.textContent = view ? annualSummaryText(view) : '';
  if (!annualSummaryBound) {
    annualSummaryBound = true;
    $('#annualSummaryYear')?.addEventListener('change', () => renderAnnualSummary());
    $('#annualSummaryExportBtn')?.addEventListener('click', () => {
      const currentYear = $('#annualSummaryYear')?.value ?? localDate().slice(0, 4);
      if (!validAnnualYear(currentYear)) { toast('Pick a valid year first.'); return; }
      const currentSnapshots = loadMonthSnapshots();
      const currentCustomers = churnSummaryCustomers();
      const currentRows = monthsOfYear(currentYear).map((month) => {
        const snap = findSnapshot(currentSnapshots, month);
        const churn = buildMonthlyChurnSummary({ month, customers: currentCustomers, atRisk: [] });
        return {
          month,
          collections: snap ? snap.collectionsCents / 100 : null,
          expenses: snap ? snap.expensesCents / 100 : null,
          newCustomers: churn ? churn.newCustomers : null,
          departed: churn ? churn.departed : null,
          customersStart: churn ? churn.start : null,
          customersEnd: churn ? churn.end : null,
          churnRate: churn ? churn.churnRate : null,
          snapshotClosed: !!snap,
        };
      });
      const current = buildAnnualSummary({ year: currentYear, months: currentRows });
      if (current) downloadCsvFile(annualSummaryFilename(current.year), annualSummaryCsv(current));
    });
  }
}
const ENQUIRY_LOG_KEY = 'shahdara_enquiry_log_v1';
let enquiryLogBound = false;
