  // SISP-37: suspense (unidentified) wallet payment register — claim
  // reuses quick collection, then persists exactly like a single quick
  // collection; the register entry is marked claimed, never deleted.
  // SISP-179: suggestion chips read pending balances off the core
  // allocation engine; the allocations result is memoized per state
  // object (state is replaced on every save, so the cache can never go
  // stale) and suspense-payments.js stays a leaf module.
  let suspenseSuggestionAllocations = null;
  let suspenseSuggestionAllocationsState = null;
  suspensePaymentsModalController = setupSuspensePaymentsModal(() => state, {
    onEntriesChanged: () => renderDashboard(),
    onToast: (msg, opts) => toast(msg, opts),
    onConfirm: (opts) => appConfirm(opts),
    currentMonth: () => monthsForHistory(new Date())[0],
    pendingBalanceOf: (customer) => {
      if (suspenseSuggestionAllocationsState !== state) {
        suspenseSuggestionAllocations = calculatePaymentAllocations(state);
        suspenseSuggestionAllocationsState = state;
      }
      return suspensePendingBalanceCents(suspenseSuggestionAllocations, customer);
    },
    onClaim: (entry, { customerId, month }) => {
      const result = claimSuspensePayment(state, loadSuspensePayments(), entry.suspenseId, {
        customerId,
        month,
        date: entry.date,
        execute: executeQuickCollection
      });
      state = result.nextState;
      saveSuspensePayments(result.entries);
      save();
      renderDetail();
      renderTransactions();
      renderMonthlyReport();
      renderDashboard();
      const customer = state.customers.find(c => String(c.id) === String(customerId));
      return {
        ...result,
        receipt: buildSuspenseReceipt({
          entry: result.entry,
          customerName: customer?.name ?? result.entry.claimedCustomerName,
          customerNumber: customer?.customerNumber ?? '',
          month,
          receiptNumber: result.paymentReceipt?.receiptNumber ?? ''
        })
      };
    }
  });
  // SISP-111: cross-customer advance credit transfer dialog — the
  // pure executor runs on a FRESH allocation snapshot inside the same
  // click (never the rendered figures), both customers and the
  // register persist together, and every surface re-renders from the
  // derived state. A reversal likewise restores both customers and
  // flips the register record; records are never deleted.
  creditTransferModalController = setupCreditTransferModal(() => state, {
    allocationsFor: (s) => calculatePaymentAllocations(s),
    getTransfers: () => loadCreditTransfers(),
    today: () => getTodayDateString(),
    confirmAction: (opts) => appConfirm(opts),
    executeTransfer: ({ fromId, toId, amount, date, note }) => {
      const allocations = calculatePaymentAllocations(state);
      const result = executeCreditTransfer({
        fromCustomer: state.customers.find(c => String(c.id) === String(fromId)),
        toCustomer: state.customers.find(c => String(c.id) === String(toId)),
        allocations,
        transfers: loadCreditTransfers(),
        amount,
        date,
        note
      });
      const fromIdx = state.customers.findIndex(c => c.id === result.fromCustomer.id);
      if (fromIdx >= 0) state.customers[fromIdx] = result.fromCustomer;
      const toIdx = state.customers.findIndex(c => c.id === result.toCustomer.id);
      if (toIdx >= 0) state.customers[toIdx] = result.toCustomer;
      saveCreditTransfers(result.transfers);
      save();
      renderDetail();
      renderTransactions();
      renderMonthlyReport();
      renderDashboard();
      toast(t('trf_success', null, { amount: formatPKR(result.transfer.amount), name: result.transfer.toCustomerName, number: result.transfer.toCustomerNumber ?? '' }));
      return result.transfer;
    },
    executeReversal: (transferId) => {
      const transfers = loadCreditTransfers();
      const record = transfers.find(e => e.transferId === transferId);
      if (!record) throw new Error('Credit transfer not found.');
      const result = reverseCreditTransfer({
        transfers,
        transferId,
        fromCustomer: state.customers.find(c => String(c.id) === String(record.fromCustomerId)),
        toCustomer: state.customers.find(c => String(c.id) === String(record.toCustomerId)),
        date: getTodayDateString()
      });
      const fromIdx = state.customers.findIndex(c => c.id === result.fromCustomer.id);
      if (fromIdx >= 0) state.customers[fromIdx] = result.fromCustomer;
      const toIdx = state.customers.findIndex(c => c.id === result.toCustomer.id);
      if (toIdx >= 0) state.customers[toIdx] = result.toCustomer;
      saveCreditTransfers(result.transfers);
      save();
      renderDetail();
      renderTransactions();
      renderMonthlyReport();
      renderDashboard();
      toast(t('trf_reversed_ok', null, { id: transferId }));
      return result.transfer;
    }
  });
  // SISP-107: supplier payable khata — logging a purchase runs the
  // SISP-18 stock-in path (addMovement -> sisp_inventory_v1) and stamps
  // the resulting movement id onto the khata record; the upfront payment
  // and every later payout mirror into Expenses via
  // recordSupplierKhataExpenseSync, so P&L counts each rupee once.
  supplierKhataModalController = setupSupplierKhataModal(() => state, {
    onRecordsChanged: () => renderDashboard(),
    onToast: (msg, opts) => toast(msg, opts),
    onLogPurchase: (fields) => {
      const { records, purchase } = addSupplierPurchase(loadSupplierKhata(), fields);
      const movements = addMovement(loadInventory(), {
        itemId: purchase.itemId,
        kind: 'in',
        qty: purchase.qty,
        date: purchase.date,
        customerName: purchase.supplierName,
        note: `Supplier khata ${purchase.purchaseId}`
      });
      const movement = movements[movements.length - 1];
      const stamped = stampStockMovement(records, purchase.purchaseId, movement?.id ?? '');
      saveSupplierKhata(stamped);
      saveInventory(movements);
      recordSupplierKhataExpenseSync();
      save();
      renderDashboard();
      return stamped.find((r) => r.purchaseId === purchase.purchaseId) ?? purchase;
    },
    onRecordPayout: (purchaseId, payload) => {
      const result = addSupplierPayout(loadSupplierKhata(), purchaseId, payload);
      saveSupplierKhata(result.records);
      recordSupplierKhataExpenseSync();
      save();
      renderDashboard();
      return result;
    }
  });
  // SISP-100: System Health Center — read-only telemetry over every
  // ledger. Archive Export reuses the shipped JSON backup download
  // button's own handler (createJsonBackup + backupExtras), so the
  // export is byte-for-byte the owner's normal backup.
  systemHealthCenterController = setupSystemHealthCenter({
    getState: () => state,
    getStorage: () => localStorage,
    onArchiveExport: () => { $('#downloadJsonBackupButton')?.click(); },
    onToast: (msg, opts) => toast(msg, opts)
  });
  // SISP-99: keyboard-first speed batch counter entry — every row is
  // recorded through executeQuickCollection (the same payment path as a
  // hand-entered Quick Collect), then persisted exactly like a single
  // quick collection. Rows that fail are reported back per-row by the
  // batch; already-recorded rows stay recorded.
  speedCounterEntryModalController = setupSpeedCounterEntryModal(() => state, {
    onToast: (msg, opts) => toast(msg, opts),
    onConfirm: (opts) => appConfirm(opts),
    currentMonth: () => monthsForHistory(new Date())[0],
    today: () => pakistanToday(),
    onRecordBatch: (rows, { date, month }) => {
      const result = submitSpeedEntryBatch(state, rows, {
        date, month, execute: executeQuickCollection
      });
      if (result.recordedCount > 0) {
        state = result.nextState;
        save();
        renderDetail();
        renderTransactions();
        renderMonthlyReport();
        renderDashboard();
      }
      return result;
    }
  });
